window.VML_DONNEES_EMBARQUEES = {"enigmes":{"version":1,"niveaux":[{"id":"mousse","nom":"Observateur","icone":"🌤️","equivalent":"≈ CE2","profil":"énigmes courtes, vocabulaire simple, aides renforcées (premier indice offert, fiche mise en évidence)"},{"id":"matelot","nom":"Releveur","icone":"🌡️","equivalent":"≈ CM1","profil":"cœur de programme CM1"},{"id":"timonier","nom":"Météorologue","icone":"🌬️","equivalent":"≈ CM2","profil":"cœur de programme CM2, plus d'éléments, vocabulaire précis"},{"id":"lieutenant","nom":"Prévisionniste","icone":"📡","equivalent":"≈ 6ᵉ","profil":"raisonnement en deux étapes, documents à croiser, justification"},{"id":"second","nom":"Climatologue","icone":"🌍","equivalent":"≈ 5ᵉ","profil":"synthèse, données chiffrées, pièges de logique, justification"}],"escales":[{"numero":1,"id":"l-abri-meteo-mesurer-la-temperature","titre":"L'abri météo","lieu":"🌡️ L'abri météo, dans la cour de l'école","matiere":"","periode_conseillee":"","episode":"Au bout de la cour, sur une petite pelouse, se dresse une boîte blanche à persiennes, montée sur un pied. Sa porte bat au vent. Le thermomètre a été sorti de l'abri et posé sur le muret, en plein soleil.","scenarimage":"","mot":"MESURER","mot_origine":"Le mot-clé de la salle 1.","air":null,"cinematique_ouverture":"transition-e1","cinematique_fin":"fin-e1","etats_decor":[],"enigmes":[{"id":"e1-1","escale":1,"ordre":1,"titre":"Lire le thermomètre","decor":"abri","objet_principal":"objet-1","objets_cliquables":["objet-1","objet-2","objet-3","objet-4"],"personnage_emetteur":"vasseur","probleme_narratif":"Madame Vasseur attend le relevé de température de l'abri.","enjeu":"Un mauvais relevé fausse toute la météo du jour.","episode_du_roman":"Fondation La main à la pâte, « Construire quelques instruments d'une station météorologique » (cycle 3) ; Relevés de la station fictive de l","competence_programme":"Lire un thermomètre, y compris sous zéro","pourquoi_ce_savoir_ici":"La salle « L'abri météo — mesurer la température » repose sur cette notion.","reaction_du_decor":{"effet":"calme","description":"Le liquide du thermomètre monte doucement."},"liberte_ou_anachronisme":"Aucune liberté particulière signalée (jeu migré).","lecon":"thermometre","type":"instrument","niveau_variantes":"Observateur (instrument) ; Releveur (instrument) ; Météorologue (instrument) ; Prévisionniste (instrument) ; Climatologue (instrument). Mousse : indices renvoyant à la fiche, énoncés courts ; lieutenant et second : justification par une phrase de la fiche.","correction_origine":"On lit le nombre de la graduation où s'arrête le haut du liquide. Sous zéro, on compte vers le bas et on écrit le signe moins : −4 °C se lit « moins quatre degrés ». Mercredi, la température la plus haute était de 21 °C, à 15 h.","matelot":{"instrument":"thermometre","unite":"°C","min":0,"max":30,"pas":1,"etiquettes":5,"items":[{"libelle":"Mercredi, 8 h","mode":"lire","valeur":12},{"libelle":"Mercredi, midi","mode":"lire","valeur":18},{"libelle":"Mercredi, 15 h","mode":"lire","valeur":21}],"consigne":"Voici trois relevés du thermomètre de l'école, mercredi, le jour de l'orage. Regarde où s'arrête le liquide rouge, compte les graduations, puis écris la température lue sous chaque thermomètre. Une petite graduation vaut <b>1 degré</b>.","indices":["Les grands traits portent un nombre : 0, 5, 10, 15, 20… Entre deux grands traits, il y a 5 petites graduations.","Pars du grand trait juste en dessous du liquide, puis compte les petits traits jusqu'au sommet du liquide.","Réponses : un nombre entre 10 et 25 pour chaque thermomètre. Le plus chaud est celui de 15 h."],"dialogue":"Regardez ce thermomètre, posé en plein soleil sur le muret : il ne mesure plus l'air, il mesure le soleil ! Un thermomètre se lit à l'ombre, dans son abri, et toujours à la même hauteur. Premier module : apprenez à lire la température, puis remettez l'instrument à sa place."},"timonier":{"instrument":"thermometre","unite":"°C","min":-10,"max":30,"pas":1,"etiquettes":5,"items":[{"libelle":"Mercredi, 8 h","mode":"lire","valeur":12},{"libelle":"Mercredi, 15 h","mode":"lire","valeur":21},{"libelle":"Un matin de janvier","mode":"lire","valeur":-4},{"libelle":"Règle : une nuit de gel à −3 °C","mode":"regler","valeur":-3,"depart":0}],"consigne":"Lis les trois premiers thermomètres et écris la température (attention au signe <b>moins</b> sous zéro). Pour le quatrième, utilise ▲ et ▼ (ou clique sur l'échelle) pour régler le liquide sur la température demandée. Une petite graduation vaut 1 degré.","indices":["Repère d'abord le trait du 0 (en pointillés). Au-dessus, les températures sont positives ; en dessous, négatives.","Pour une température négative, compte les graduations en descendant depuis 0 et écris le signe « − » devant.","Pour régler −3 °C : le liquide doit s'arrêter trois petites graduations sous le 0."],"dialogue":"Regardez ce thermomètre, posé en plein soleil sur le muret : il ne mesure plus l'air, il mesure le soleil ! Un thermomètre se lit à l'ombre, dans son abri, et toujours à la même hauteur. Premier module : apprenez à lire la température, puis remettez l'instrument à sa place."},"mousse":{"type":"instrument","instrument":"thermometre","unite":"°C","min":0,"max":30,"pas":1,"etiquettes":5,"items":[{"libelle":"Lundi, 8 h","mode":"lire","valeur":10},{"libelle":"Lundi, 15 h","mode":"lire","valeur":20}],"consigne":"Voici deux relevés du thermomètre de l'école. Regarde où s'arrête le liquide rouge et écris la température lue sous chaque thermomètre. Une petite graduation vaut <b>1 degré</b>.","indices":["Ouvre la fiche « Mesurer la température de l'air » dans la Bibliothèque.","Les grands traits portent un nombre : 0, 5, 10, 15, 20…","Le plus chaud est celui de l'après-midi."],"dialogue":"Regardez ce thermomètre, posé en plein soleil sur le muret : il ne mesure plus l'air, il mesure le soleil ! Un thermomètre se lit à l'ombre, dans son abri, et toujours à la même hauteur. Premier module : apprenez à lire la température, puis remettez l'instrument à sa place."},"lieutenant":{"type":"instrument","instrument":"thermometre","unite":"°C","min":0,"max":30,"pas":0.5,"etiquettes":5,"items":[{"libelle":"Jeudi, 8 h","mode":"lire","valeur":8.5},{"libelle":"Jeudi, 15 h","mode":"lire","valeur":14.5},{"libelle":"Règle : 11,5 °C","mode":"regler","valeur":11.5,"depart":5}],"consigne":"Voici deux relevés de jeudi. Ici, une petite graduation vaut <b>0,5 °C</b> : écris la température avec une virgule si besoin. Pour le troisième, règle le liquide avec ▲ et ▼. Puis choisis la phrase de la fiche qui explique comment lire un thermomètre.","indices":["Entre deux grands traits (5 °C), il y a 10 petites graduations.","Deux petites graduations font 1 degré.","Lis la graduation au sommet du liquide."],"justification":{"question":"Quelle phrase de la fiche explique comment lire un thermomètre ?","options":["On mesure la température de l'air avec un thermomètre ou un capteur électronique, en degrés Celsius (°C).","On lit la graduation qui correspond au sommet du liquide, les yeux à sa hauteur.","Sous le zéro, les températures sont négatives : plus le nombre après le signe moins est grand, plus il fait froid (−6 °C est plus froid que −1 °C).","La température minimale est la plus basse de la journée, la maximale la plus haute."],"bonne":1},"dialogue":"Regardez ce thermomètre, posé en plein soleil sur le muret : il ne mesure plus l'air, il mesure le soleil ! Un thermomètre se lit à l'ombre, dans son abri, et toujours à la même hauteur. Premier module : apprenez à lire la température, puis remettez l'instrument à sa place."},"second":{"type":"instrument","instrument":"thermometre","unite":"°C","min":-20,"max":40,"pas":2,"etiquettes":10,"items":[{"libelle":"Un matin d'hiver","mode":"lire","valeur":-8},{"libelle":"Un après-midi d'été","mode":"lire","valeur":26},{"libelle":"Règle : une nuit de gel à −12 °C","mode":"regler","valeur":-12,"depart":0}],"consigne":"Voici deux relevés et un réglage. Ici, une petite graduation vaut <b>2 °C</b> : attention au signe <b>moins</b> sous zéro. Pour le troisième, règle le liquide avec ▲ et ▼. Puis choisis la phrase de la fiche qui explique les températures négatives.","indices":["Repère le trait du 0.","Sous le zéro, compte les graduations en descendant.","Chaque petite graduation vaut 2 °C."],"justification":{"question":"Quelle phrase de la fiche explique les températures négatives ?","options":["On lit la graduation qui correspond au sommet du liquide, les yeux à sa hauteur.","La température minimale est la plus basse de la journée, la maximale la plus haute.","Sous le zéro, les températures sont négatives : plus le nombre après le signe moins est grand, plus il fait froid (−6 °C est plus froid que −1 °C).","Le maximum n'a pas lieu à midi : il arrive souvent en milieu d'après-midi, quand le sol a chauffé toute la journée."],"bonne":2},"dialogue":"Regardez ce thermomètre, posé en plein soleil sur le muret : il ne mesure plus l'air, il mesure le soleil ! Un thermomètre se lit à l'ombre, dans son abri, et toujours à la même hauteur. Premier module : apprenez à lire la température, puis remettez l'instrument à sa place."}},{"id":"e1-2","escale":1,"ordre":2,"titre":"Où placer le thermomètre ?","decor":"abri","objet_principal":"objet-2","objets_cliquables":["objet-1","objet-2","objet-3","objet-4"],"personnage_emetteur":"vasseur","probleme_narratif":"Tiago se demande où installer le thermomètre.","enjeu":"Mal placé, le thermomètre ne dit pas la vraie température.","episode_du_roman":"Météo-France, « Qu'est-ce que la température ? » : mesure sous abri, à 1,50 m du sol","competence_programme":"Lire un thermomètre, y compris sous zéro","pourquoi_ce_savoir_ici":"La salle « L'abri météo — mesurer la température » repose sur cette notion.","reaction_du_decor":{"effet":"carte","description":"L'abri s'ouvre et laisse passer l'air."},"liberte_ou_anachronisme":"Aucune liberté particulière signalée (jeu migré).","lecon":"thermometre","type":"qcm","niveau_variantes":"Observateur (qcm) ; Releveur (qcm) ; Météorologue (qcm) ; Prévisionniste (vraifaux) ; Climatologue (qcm). Mousse : indices renvoyant à la fiche, énoncés courts ; lieutenant et second : justification par une phrase de la fiche.","correction_origine":"Météo-France mesure la température de l'air sous abri, à 1,50 m du sol, dans un abri blanc et percé d'ouvertures. L'abri laisse passer l'air mais protège le capteur du soleil et de la pluie : ainsi, on mesure bien l'air, et toutes les stations peuvent comparer leurs relevés.","matelot":{"questions":[{"q":"Pour mesurer la température de l'air, le thermomètre doit être…","options":["à l'ombre, dans son abri","en plein soleil","posé sur le sol"],"bonne":0,"explication":"Au soleil, le thermomètre chauffe lui-même : il indique plus que la température de l'air."},{"q":"À quelle hauteur place-t-on le thermomètre dans l'abri ?","options":["à 1,50 m du sol","au ras du sol","sur le toit de l'école"],"bonne":0,"explication":"C'est la hauteur utilisée par Météo-France : toutes les stations mesurent de la même façon."},{"q":"Pourquoi l'abri météo est-il blanc ?","options":["pour renvoyer la lumière du soleil","pour qu'on le voie la nuit","parce que c'est plus joli"],"bonne":0,"explication":"Une couleur claire chauffe moins au soleil qu'une couleur foncée."}],"consigne":"Le thermomètre a été retrouvé en plein soleil, sur le muret. Réponds aux trois questions pour le remettre à la bonne place, puis vérifie.","indices":["Au soleil, un objet chauffe beaucoup plus que l'air autour de lui.","L'abri est blanc : le blanc renvoie la lumière du soleil.","La bonne hauteur est à peu près celle de ta tête quand tu es debout : 1,50 m."],"dialogue":"Où placer le thermomètre pour une mesure juste ? Répondez."},"timonier":{"questions":[{"q":"Pourquoi l'abri est-il percé d'ouvertures (des persiennes) ?","options":["pour que l'air circule autour du capteur","pour que la pluie mouille le thermomètre","pour que le soleil éclaire le thermomètre","pour faire moins lourd"],"bonne":0,"explication":"L'air doit circuler : le capteur prend alors la température de l'air qui l'entoure."},{"q":"Deux écoles comparent leurs températures. Pourquoi mesurent-elles toutes les deux à 1,50 m, sous abri ?","options":["pour que leurs mesures soient comparables","parce que c'est plus facile à lire","parce que l'air est plus chaud à 1,50 m","parce que c'est la taille du thermomètre"],"bonne":0,"explication":"Les mêmes règles de mesure, partout, permettent d'échanger et de comparer les relevés (normes de l'Organisation météorologique mondiale)."},{"q":"La température maximale d'une journée, c'est…","options":["la température la plus haute relevée ce jour-là","la température relevée à midi","la moyenne de la journée","la température relevée au soleil"],"bonne":0,"explication":"Le maximum n'a pas lieu forcément à midi : mercredi, il a été atteint vers 15 h."}],"consigne":"Réponds aux trois questions. Une seule réponse est juste par question : pense à ce qui pourrait fausser la mesure.","indices":["On veut mesurer la température de l'air, pas celle du sol ni celle d'un mur.","Pour comparer deux stations, il faut qu'elles mesurent de la même façon.","Les ouvertures de l'abri laissent circuler l'air ; le toit arrête le soleil et la pluie."],"dialogue":"Où placer le thermomètre pour une mesure juste ? Répondez."},"mousse":{"type":"qcm","questions":[{"q":"Pour mesurer la température de l'air, le thermomètre doit être…","options":["à l'ombre, dans son abri","en plein soleil","posé sur le sol"],"bonne":0,"explication":"Au soleil, il chauffe lui-même."}],"consigne":"Le thermomètre a été retrouvé en plein soleil. Lis la question, clique sur la bonne réponse, puis vérifie.","indices":["Ouvre la fiche « Mesurer la température de l'air ».","Au soleil, un objet chauffe beaucoup.","L'abri est blanc."],"dialogue":"J'ai quelques questions pour vous. Lisez bien le document avant de répondre."},"lieutenant":{"type":"vraifaux","affirmations":[{"txt":"L'abri est blanc et percé d'ouvertures.","vrai":true,"explication":"L'air y circule."},{"txt":"Le thermomètre est placé au ras du sol.","vrai":false,"explication":"À 1,50 m du sol."},{"txt":"Le capteur est protégé du soleil et de la pluie.","vrai":true,"explication":"Par l'abri."},{"txt":"Toutes les stations suivent les mêmes règles.","vrai":true,"explication":"Fixées par l'Organisation météorologique mondiale."},{"txt":"Le thermomètre se met en plein soleil pour être plus précis.","vrai":false,"explication":"Il indiquerait plus que la température de l'air."}],"consigne":"Tiago a noté cinq phrases sur l'abri météo. Pour chacune, réponds « Vrai » ou « Faux », puis choisis la phrase de la fiche qui décrit l'abri.","indices":["Un abri blanc renvoie la lumière.","La hauteur est de 1,50 m.","Pour la justification : cherche la phrase qui nomme Météo-France."],"justification":{"question":"Quelle phrase de la fiche décrit l'abri météo ?","options":["Toutes les stations suivent les mêmes règles, fixées par l'Organisation météorologique mondiale.","Météo-France la mesure sous abri, à 1,50 m du sol, dans un abri blanc et percé d'ouvertures : l'air y circule, mais le capteur est protégé du rayonnement du soleil et de la pluie.","On mesure la température de l'air avec un thermomètre ou un capteur électronique, en degrés Celsius (°C).","Le maximum n'a pas lieu à midi : il arrive souvent en milieu d'après-midi, quand le sol a chauffé toute la journée."],"bonne":1},"dialogue":"Voici mes affirmations. À vous de dire lesquelles sont vraies."},"second":{"type":"qcm","questions":[{"q":"Quelle mesure est la plus fiable ?","options":["Celle de Léo, sous abri","Celle de Hugo, au soleil","Les deux","Aucune"],"bonne":0,"explication":"Le soleil fausse la mesure."},{"q":"Pourquoi les deux mesures ne sont-elles pas comparables ?","options":["Elles ne suivent pas les mêmes règles de mesure","Les élèves sont différents","Les thermomètres sont en verre","Il fait nuit"],"bonne":0,"explication":"Toutes les stations suivent les mêmes règles."},{"q":"Quel est l'écart entre les deux mesures ?","options":["9 °C","18 °C","27 °C","45 °C"],"bonne":0,"explication":"27 − 18 = 9."}],"consigne":"<div class='doc-carnet'><b>Rapport de Tiago</b> (inventé pour le jeu). Deux élèves comparent leurs relevés. Léo mesure sous abri à 1,50 m ; Hugo pose son thermomètre sur le muret, en plein soleil. Léo relève 18 °C, Hugo 27 °C.</div> Réponds aux trois questions, puis choisis la phrase de la fiche qui justifie la question 2.","indices":["Un thermomètre au soleil chauffe lui-même.","Pour comparer, il faut les mêmes règles.","Soustrais 18 de 27."],"justification":{"question":"Quelle phrase de la fiche justifie ta réponse à la question 2 ?","options":["Météo-France la mesure sous abri, à 1,50 m du sol, dans un abri blanc et percé d'ouvertures : l'air y circule, mais le capteur est protégé du rayonnement du soleil et de la pluie.","Toutes les stations suivent les mêmes règles, fixées par l'Organisation météorologique mondiale.","On lit la graduation qui correspond au sommet du liquide, les yeux à sa hauteur.","La température minimale est la plus basse de la journée, la maximale la plus haute."],"bonne":1},"dialogue":"J'ai quelques questions pour vous. Lisez bien le document avant de répondre."}},{"id":"e1-3","escale":1,"ordre":3,"titre":"Du plus froid au plus chaud","decor":"abri","objet_principal":"objet-3","objets_cliquables":["objet-1","objet-2","objet-3","objet-4"],"personnage_emetteur":"vasseur","probleme_narratif":"Lina range ses relevés de la semaine.","enjeu":"Sans l'ordre, la tendance de la semaine est perdue.","episode_du_roman":"Relevés de la station fictive de l'école (données du jeu)","competence_programme":"Lire un thermomètre, y compris sous zéro","pourquoi_ce_savoir_ici":"La salle « L'abri météo — mesurer la température » repose sur cette notion.","reaction_du_decor":{"effet":"ouverture","description":"Les chiffres se rangent sur le panneau."},"liberte_ou_anachronisme":"Aucune liberté particulière signalée (jeu migré).","lecon":"thermometre","type":"ordre","niveau_variantes":"Observateur (ordre) ; Releveur (ordre) ; Météorologue (ordre) ; Prévisionniste (ordre) ; Climatologue (ordre). Mousse : indices renvoyant à la fiche, énoncés courts ; lieutenant et second : justification par une phrase de la fiche.","correction_origine":"Pour comparer des températures, on les place sur la graduation du thermomètre : plus on est bas, plus il fait froid. −6 °C est plus froid que −1 °C, qui est plus froid que 0 °C.","matelot":{"items":[{"txt":"7 °C","sous":"vendredi, au lever du jour","rang":1},{"txt":"12 °C","sous":"mercredi, 8 h","rang":2},{"txt":"16 °C","sous":"vendredi, après-midi","rang":3},{"txt":"18 °C","sous":"mercredi, midi","rang":4},{"txt":"21 °C","sous":"mercredi, 15 h","rang":5}],"consigne":"Le cahier de relevés est trempé : les températures sont mélangées. Range-les <b>de la plus froide (en haut) à la plus chaude (en bas)</b> avec les flèches ▲ ▼.","indices":["Compare d'abord les nombres qui n'ont qu'un chiffre.","La plus froide est 7 °C.","La plus chaude est 21 °C : c'est mercredi à 15 h."],"dialogue":"Rangez les relevés du plus froid au plus chaud !"},"timonier":{"items":[{"txt":"−6 °C","sous":"une nuit de janvier","rang":1},{"txt":"−1 °C","sous":"un matin de gel léger","rang":2},{"txt":"0 °C","sous":"l'eau commence à geler","rang":3},{"txt":"7 °C","sous":"vendredi, au lever du jour","rang":4},{"txt":"12 °C","sous":"mercredi, 8 h","rang":5},{"txt":"21 °C","sous":"mercredi, 15 h","rang":6}],"consigne":"Range ces températures <b>de la plus froide (en haut) à la plus chaude (en bas)</b>. Attention : sous zéro, plus le nombre après le signe moins est grand, plus il fait froid.","indices":["Les températures négatives sont toutes plus froides que 0 °C.","Imagine un thermomètre : −6 est plus bas que −1.","Ordre attendu : d'abord les deux températures négatives, puis 0 °C, puis les positives."],"dialogue":"Rangez les relevés du plus froid au plus chaud !"},"mousse":{"type":"ordre","items":[{"txt":"5 °C","rang":1,"sous":"lundi, 8 h"},{"txt":"12 °C","rang":2,"sous":"lundi, midi"},{"txt":"19 °C","rang":3,"sous":"lundi, 15 h"}],"consigne":"Le cahier de relevés est mélangé. Range les températures de la plus froide (en haut) à la plus chaude (en bas) avec les flèches ▲ ▼.","indices":["Ouvre la fiche « Mesurer la température de l'air ».","Compare les nombres : le plus petit est le plus froid.","19 est le plus grand."],"dialogue":"Mes étapes sont mélangées. Remettez-les dans le bon ordre."},"lieutenant":{"type":"ordre","items":[{"txt":"−9 °C","rang":1,"sous":"une nuit de janvier"},{"txt":"−2 °C","rang":2,"sous":"un matin de gel"},{"txt":"0 °C","rang":3,"sous":"l'eau commence à geler"},{"txt":"6 °C","rang":4,"sous":"un matin d'avril"},{"txt":"17 °C","rang":5,"sous":"un après-midi de mai"}],"consigne":"Lina a noté cinq températures de la semaine, avec des signes moins. Range-les de la plus froide (en haut) à la plus chaude (en bas), puis choisis la phrase de la fiche qui explique l'ordre des températures négatives.","indices":["Les températures négatives sont les plus froides.","−9 est plus bas que −2.","Le plus chaud est 17 °C."],"justification":{"question":"Quelle phrase de la fiche explique l'ordre des températures négatives ?","options":["Sous le zéro, les températures sont négatives : plus le nombre après le signe moins est grand, plus il fait froid (−6 °C est plus froid que −1 °C).","On lit la graduation qui correspond au sommet du liquide, les yeux à sa hauteur.","La température minimale est la plus basse de la journée, la maximale la plus haute.","Toutes les stations suivent les mêmes règles, fixées par l'Organisation météorologique mondiale."],"bonne":0},"dialogue":"Mes étapes sont mélangées. Remettez-les dans le bon ordre."},"second":{"type":"ordre","items":[{"txt":"−3 °C","rang":1,"sous":"minimum, à 6 h"},{"txt":"2 °C","rang":2,"sous":"à 9 h"},{"txt":"9 °C","rang":3,"sous":"à midi"},{"txt":"12 °C","rang":4,"sous":"à 17 h"},{"txt":"14 °C","rang":5,"sous":"maximum, à 15 h"}],"consigne":"Lina range des mesures d'une même journée. Range-les de la plus froide (en haut) à la plus chaude (en bas), puis choisis la phrase de la fiche qui explique pourquoi le maximum n'est pas à midi.","indices":["Compare d'abord les signes.","Le maximum est atteint en milieu d'après-midi.","−3 est le plus bas."],"justification":{"question":"Quelle phrase de la fiche explique pourquoi le maximum n'est pas à midi ?","options":["La température minimale est la plus basse de la journée, la maximale la plus haute.","Le maximum n'a pas lieu à midi : il arrive souvent en milieu d'après-midi, quand le sol a chauffé toute la journée.","Sous le zéro, les températures sont négatives : plus le nombre après le signe moins est grand, plus il fait froid (−6 °C est plus froid que −1 °C).","Météo-France la mesure sous abri, à 1,50 m du sol, dans un abri blanc et percé d'ouvertures : l'air y circule, mais le capteur est protégé du rayonnement du soleil et de la pluie."],"bonne":1},"dialogue":"Mes étapes sont mélangées. Remettez-les dans le bon ordre."}},{"id":"e1-4","escale":1,"ordre":4,"titre":"Mesure fiable ou mesure faussée ?","decor":"abri","objet_principal":"objet-4","objets_cliquables":["objet-1","objet-2","objet-3","objet-4"],"personnage_emetteur":"vasseur","probleme_narratif":"Keita trie les mesures fiables et faussées.","enjeu":"Une mesure faussée entre dans les relevés.","episode_du_roman":"Météo-France, « Qu'est-ce que la température ? » : mesure sous abri, à 1,50 m du sol ; Fondation La main à la pâte, « Construire quelques in","competence_programme":"Lire un thermomètre, y compris sous zéro","pourquoi_ce_savoir_ici":"La salle « L'abri météo — mesurer la température » repose sur cette notion.","reaction_du_decor":{"effet":"lumiere","description":"Les fiches se classent en deux piles."},"liberte_ou_anachronisme":"Aucune liberté particulière signalée (jeu migré).","lecon":"thermometre","type":"tri","niveau_variantes":"Météorologue (tri) ; Prévisionniste (tri) ; Climatologue (tri). Mousse : indices renvoyant à la fiche, énoncés courts ; lieutenant et second : justification par une phrase de la fiche.","correction_origine":"Une mesure fiable se fait à l'ombre, sous abri ventilé, à 1,50 m, loin d'une source de chaleur, et toujours de la même façon (même lieu, même heure). Un thermomètre tenu à la main, posé au soleil ou près d'un mur chaud mesure autre chose que l'air.","niveaux":["timonier","lieutenant","second"],"timonier":{"colonnes":[{"id":"fiable","titre":"Mesure fiable"},{"id":"faussee","titre":"Mesure faussée"}],"cartes":[{"txt":"Léo lit le thermomètre dans l'abri, à 1,50 m, tous les jours à 8 h.","col":"fiable"},{"txt":"Sara attend deux minutes avant de lire, sans toucher le thermomètre.","col":"fiable"},{"txt":"Noé note aussi le jour et l'heure à côté de chaque mesure.","col":"fiable"},{"txt":"Inès tient le thermomètre serré dans sa main pendant la lecture.","col":"faussee"},{"txt":"Hugo pose le thermomètre sur le muret, en plein soleil.","col":"faussee"},{"txt":"Maëlle accroche le thermomètre contre le mur de la cantine, près de la sortie d'air chaud.","col":"faussee"}],"consigne":"Lina a noté comment chaque camarade a mesuré la température. Clique sur une carte, puis sur la colonne qui convient. Une mesure est <b>fiable</b> si elle respecte les règles de la station.","indices":["Pose-toi la question : est-ce que quelque chose réchauffe ou refroidit le thermomètre, en plus de l'air ?","La main, le soleil, un mur chauffé, le sol : tout cela fausse la mesure.","Il y a trois mesures fiables et trois mesures faussées."],"dialogue":"Mesure fiable ou mesure faussée ? Triez les fiches."},"lieutenant":{"type":"tri","colonnes":[{"id":"fiable","titre":"Mesure fiable"},{"id":"faussee","titre":"Mesure faussée"}],"cartes":[{"txt":"Zoé lit le thermomètre sous abri, à 1,50 m.","col":"fiable"},{"txt":"Karim note l'heure à côté de chaque mesure.","col":"fiable"},{"txt":"Iris attend un peu avant de lire, sans toucher le thermomètre.","col":"fiable"},{"txt":"Paul pose le thermomètre sur le sol en plein soleil.","col":"faussee"},{"txt":"Alix tient le thermomètre serré dans sa main.","col":"faussee"},{"txt":"Nora accroche le thermomètre contre un mur chauffé.","col":"faussee"}],"consigne":"Lina a noté comment chaque camarade a mesuré la température. Range chaque mesure : fiable ou faussée ? Puis choisis la phrase de la fiche qui donne la hauteur de mesure.","indices":["Le soleil, la main et un mur chaud faussent la mesure.","La mesure fiable respecte les règles de la station.","Pour la justification : cherche la phrase qui cite 1,50 m."],"justification":{"question":"Quelle phrase de la fiche donne la hauteur de mesure ?","options":["On lit la graduation qui correspond au sommet du liquide, les yeux à sa hauteur.","Toutes les stations suivent les mêmes règles, fixées par l'Organisation météorologique mondiale.","Météo-France la mesure sous abri, à 1,50 m du sol, dans un abri blanc et percé d'ouvertures : l'air y circule, mais le capteur est protégé du rayonnement du soleil et de la pluie.","Le maximum n'a pas lieu à midi : il arrive souvent en milieu d'après-midi, quand le sol a chauffé toute la journée."],"bonne":2},"dialogue":"Il faut tout ranger. Placez chaque carte dans la bonne colonne."},"second":{"type":"tri","colonnes":[{"id":"oui","titre":"La fiche l'affirme"},{"id":"non","titre":"La fiche ne l'affirme pas"}],"cartes":[{"txt":"La température se mesure en degrés Celsius.","col":"oui"},{"txt":"Le maximum arrive souvent en milieu d'après-midi.","col":"oui"},{"txt":"−6 °C est plus froid que −1 °C.","col":"oui"},{"txt":"Le thermomètre se lit à midi seulement.","col":"non"},{"txt":"La température se mesure en kilomètres par heure.","col":"non"},{"txt":"Le minimum est la valeur la plus haute.","col":"non"}],"consigne":"Lina classe des affirmations sur la température. Range chaque carte : la fiche l'affirme, ou elle ne l'affirme pas. Puis choisis la phrase de la fiche qui définit minimum et maximum.","indices":["Les degrés Celsius sont l'unité.","Le maximum est la valeur la plus haute.","Plus le nombre après le moins est grand, plus il fait froid."],"justification":{"question":"Quelle phrase de la fiche définit minimum et maximum ?","options":["Le maximum n'a pas lieu à midi : il arrive souvent en milieu d'après-midi, quand le sol a chauffé toute la journée.","La température minimale est la plus basse de la journée, la maximale la plus haute.","Sous le zéro, les températures sont négatives : plus le nombre après le signe moins est grand, plus il fait froid (−6 °C est plus froid que −1 °C).","On mesure la température de l'air avec un thermomètre ou un capteur électronique, en degrés Celsius (°C)."],"bonne":1},"dialogue":"Il faut tout ranger. Placez chaque carte dans la bonne colonne."}}]},{"numero":2,"id":"le-mat-du-vent-direction-et-vitesse","titre":"Le mât du vent","lieu":"🧭 Le mât de l'anémomètre et de la girouette","matiere":"","periode_conseillee":"","episode":"Au sommet d'un mât, des coupelles tournent et une girouette hésite. L'orage a fait pivoter la croix des points cardinaux : plus personne ne sait où est le nord.","scenarimage":"","mot":"ORIENTER","mot_origine":"Le mot-clé de la salle 2.","air":null,"cinematique_ouverture":"transition-e2","cinematique_fin":"fin-e2","etats_decor":[],"enigmes":[{"id":"e2-1","escale":2,"ordre":1,"titre":"La rose des vents","decor":"mat","objet_principal":"objet-1","objets_cliquables":["objet-1","objet-2","objet-3","objet-4"],"personnage_emetteur":"keita","probleme_narratif":"Keita demande de compléter la rose des vents.","enjeu":"Sans les points cardinaux, on se perd en mer.","episode_du_roman":"Fondation La main à la pâte, « Construire quelques instruments d'une station météorologique » (cycle 3)","competence_programme":"Utiliser les points cardinaux et la rose des vents","pourquoi_ce_savoir_ici":"La salle « Le mât du vent — direction et vitesse » repose sur cette notion.","reaction_du_decor":{"effet":"carte","description":"L'aiguille tourne et pointe le nord."},"liberte_ou_anachronisme":"Aucune liberté particulière signalée (jeu migré).","lecon":"vent","type":"plan","niveau_variantes":"Observateur (plan) ; Releveur (plan) ; Météorologue (plan) ; Prévisionniste (qcm) ; Climatologue (vraifaux). Mousse : indices renvoyant à la fiche, énoncés courts ; lieutenant et second : justification par une phrase de la fiche.","correction_origine":"Le soleil se lève à l'est et se couche à l'ouest ; en France, à midi, il est au sud. Le nord est à l'opposé. Entre deux points cardinaux, on nomme les directions intermédiaires : nord-est, sud-est, sud-ouest, nord-ouest.","matelot":{"titre":"Rose des vents de la station","colonnes":2,"cases":[{"libelle":"Là où le soleil se lève le matin","reponse":"Est"},{"libelle":"Là où le soleil se couche le soir","reponse":"Ouest"},{"libelle":"Là où se trouve le soleil à midi, en France","reponse":"Sud"},{"libelle":"À l'opposé du soleil de midi","reponse":"Nord"}],"etiquettes":["Nord","Sud","Est","Ouest"],"consigne":"L'orage a fait tourner la croix des points cardinaux. Replace les quatre points cardinaux : clique sur une étiquette, puis sur la case qui lui correspond.","indices":["Le matin, le soleil se lève à l'est.","Le soir, il se couche à l'ouest.","En France, le soleil de midi est au sud : le nord est dans ton dos."],"dialogue":"Bonjour, matelots. Sur mon bateau, deux questions décident de tout : d'où vient le vent, et à quelle vitesse il souffle. La girouette répond à la première, l'anémomètre à la seconde. Mais sans les points cardinaux, une girouette ne sert à rien. Remettez la rose des vents dans le bon sens."},"timonier":{"titre":"<svg class=\"graphe-consigne\" style=\"max-width:240px\" viewBox=\"0 0 240 240\" role=\"img\" aria-label=\"Rose des vents à huit branches numérotées de 1 à 8 ; la branche 1 est en haut, les numéros tournent dans le sens des aiguilles d'une montre\"><circle cx=\"120\" cy=\"120\" r=\"22\" fill=\"#eef3f8\" stroke=\"#5b6b7a\"/><polygon points=\"129.0,120.0 120.0,28.0 111.0,120.0\" fill=\"#1d3a8a\" stroke=\"#13286b\" stroke-width=\"1\"/><circle cx=\"120.0\" cy=\"12.0\" r=\"10\" fill=\"#fff\" stroke=\"#13286b\"/><text x=\"120.0\" y=\"16.0\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\" font-family=\"Arial,sans-serif\" fill=\"#13286b\">1</text><polygon points=\"124.9,124.9 166.7,73.3 115.1,115.1\" fill=\"#5aa0d8\" stroke=\"#13286b\" stroke-width=\"1\"/><circle cx=\"178.0\" cy=\"62.0\" r=\"10\" fill=\"#fff\" stroke=\"#13286b\"/><text x=\"178.0\" y=\"66.0\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\" font-family=\"Arial,sans-serif\" fill=\"#13286b\">2</text><polygon points=\"120.0,129.0 212.0,120.0 120.0,111.0\" fill=\"#1d3a8a\" stroke=\"#13286b\" stroke-width=\"1\"/><circle cx=\"228.0\" cy=\"120.0\" r=\"10\" fill=\"#fff\" stroke=\"#13286b\"/><text x=\"228.0\" y=\"124.0\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\" font-family=\"Arial,sans-serif\" fill=\"#13286b\">3</text><polygon points=\"115.1,124.9 166.7,166.7 124.9,115.1\" fill=\"#5aa0d8\" stroke=\"#13286b\" stroke-width=\"1\"/><circle cx=\"178.0\" cy=\"178.0\" r=\"10\" fill=\"#fff\" stroke=\"#13286b\"/><text x=\"178.0\" y=\"182.0\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\" font-family=\"Arial,sans-serif\" fill=\"#13286b\">4</text><polygon points=\"111.0,120.0 120.0,212.0 129.0,120.0\" fill=\"#1d3a8a\" stroke=\"#13286b\" stroke-width=\"1\"/><circle cx=\"120.0\" cy=\"228.0\" r=\"10\" fill=\"#fff\" stroke=\"#13286b\"/><text x=\"120.0\" y=\"232.0\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\" font-family=\"Arial,sans-serif\" fill=\"#13286b\">5</text><polygon points=\"115.1,115.1 73.3,166.7 124.9,124.9\" fill=\"#5aa0d8\" stroke=\"#13286b\" stroke-width=\"1\"/><circle cx=\"62.0\" cy=\"178.0\" r=\"10\" fill=\"#fff\" stroke=\"#13286b\"/><text x=\"62.0\" y=\"182.0\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\" font-family=\"Arial,sans-serif\" fill=\"#13286b\">6</text><polygon points=\"120.0,111.0 28.0,120.0 120.0,129.0\" fill=\"#1d3a8a\" stroke=\"#13286b\" stroke-width=\"1\"/><circle cx=\"12.0\" cy=\"120.0\" r=\"10\" fill=\"#fff\" stroke=\"#13286b\"/><text x=\"12.0\" y=\"124.0\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\" font-family=\"Arial,sans-serif\" fill=\"#13286b\">7</text><polygon points=\"124.9,115.1 73.3,73.3 115.1,124.9\" fill=\"#5aa0d8\" stroke=\"#13286b\" stroke-width=\"1\"/><circle cx=\"62.0\" cy=\"62.0\" r=\"10\" fill=\"#fff\" stroke=\"#13286b\"/><text x=\"62.0\" y=\"66.0\" font-size=\"12\" font-weight=\"bold\" text-anchor=\"middle\" font-family=\"Arial,sans-serif\" fill=\"#13286b\">8</text></svg>","colonnes":4,"cases":[{"libelle":"Branche 1","reponse":"Nord"},{"libelle":"Branche 2","reponse":"Nord-Est"},{"libelle":"Branche 3","reponse":"Est"},{"libelle":"Branche 4","reponse":"Sud-Est"},{"libelle":"Branche 5","reponse":"Sud"},{"libelle":"Branche 6","reponse":"Sud-Ouest"},{"libelle":"Branche 7","reponse":"Ouest"},{"libelle":"Branche 8","reponse":"Nord-Ouest"}],"etiquettes":["Nord","Nord-Est","Est","Sud-Est","Sud","Sud-Ouest","Ouest","Nord-Ouest"],"consigne":"Replace les huit directions sur les branches de la rose des vents. La <b>branche 1 montre le nord</b> ; les numéros tournent dans le sens des aiguilles d'une montre.","indices":["Nord en haut (1), sud en bas (5), est à droite (3), ouest à gauche (7).","Une direction intermédiaire prend le nom de ses deux voisins, en commençant par nord ou sud.","La branche 2 est entre le nord et l'est : c'est le nord-est."],"dialogue":"Bonjour, matelots. Sur mon bateau, deux questions décident de tout : d'où vient le vent, et à quelle vitesse il souffle. La girouette répond à la première, l'anémomètre à la seconde. Mais sans les points cardinaux, une girouette ne sert à rien. Remettez la rose des vents dans le bon sens."},"mousse":{"type":"plan","titre":"Rose des vents de la station","colonnes":2,"cases":[{"libelle":"Là où le soleil se lève le matin","reponse":"Est"},{"libelle":"Là où le soleil se couche le soir","reponse":"Ouest"},{"libelle":"Là où se trouve le soleil à midi, en France","reponse":"Sud"}],"etiquettes":["Est","Ouest","Sud","Nord"],"consigne":"L'orage a fait tourner la croix des points cardinaux. Replace les points cardinaux : clique sur une étiquette, puis sur la case qui lui correspond. Une étiquette est en trop.","indices":["Ouvre la fiche « Mesurer le vent : direction et vitesse » dans la Bibliothèque.","Le matin, le soleil se lève à l'est.","En France, le soleil de midi est au sud."],"dialogue":"Bonjour, matelots. Sur mon bateau, deux questions décident de tout : d'où vient le vent, et à quelle vitesse il souffle. La girouette répond à la première, l'anémomètre à la seconde. Mais sans les points cardinaux, une girouette ne sert à rien. Remettez la rose des vents dans le bon sens."},"lieutenant":{"type":"qcm","questions":[{"q":"D'où vient le vent de lundi ?","options":["Du nord-ouest","Du sud-est","Du nord-est","Du sud-ouest"],"bonne":0,"explication":"La girouette indique d'où vient le vent."},{"q":"Quelle est la force de Beaufort du vent de lundi (20 km/h) ?","options":["Force 4","Force 2","Force 6","Force 0"],"bonne":0,"explication":"20 à 28 km/h : force 4."},{"q":"Que ressent-on pour le vent de mardi (6 km/h, force 2) ?","options":["On sent le vent sur le visage, les feuilles frémissent","La fumée monte tout droit","Les grosses branches s'agitent","Des dégâts importants"],"bonne":0,"explication":"Force 2."}],"consigne":"<div class='doc-carnet'><b>Relevés du mât</b> (inventés pour le jeu). Lundi : la girouette pointe vers le nord-ouest ; l'anémomètre indique 20 km/h. Mardi : la girouette pointe vers le sud ; l'anémomètre indique 6 km/h.</div> Réponds aux trois questions, puis choisis la phrase de la fiche qui justifie la question 1.","indices":["La girouette indique d'où vient le vent.","20 à 28 km/h : force 4.","Force 2 : on sent le vent sur le visage."],"justification":{"question":"Quelle phrase de la fiche justifie ta réponse à la question 1 ?","options":["L'anémomètre mesure sa vitesse, en km/h ou en mètres par seconde (1 m/s = 3,6 km/h, car une heure compte 3 600 secondes).","Chaque direction intermédiaire prend le nom de ses deux voisines, en commençant par nord ou sud.","La girouette indique la direction d'où vient le vent : un vent de nord-ouest vient du nord-ouest.","Une pointe brève et plus forte s'appelle une rafale."],"bonne":2},"dialogue":"Bonjour, matelots. Sur mon bateau, deux questions décident de tout : d'où vient le vent, et à quelle vitesse il souffle. La girouette répond à la première, l'anémomètre à la seconde. Mais sans les points cardinaux, une girouette ne sert à rien. Remettez la rose des vents dans le bon sens."},"second":{"type":"vraifaux","affirmations":[{"txt":"La rose des vents porte quatre points cardinaux.","vrai":true,"explication":"N, E, S, O."},{"txt":"La rose des vents porte aussi quatre directions intermédiaires.","vrai":true,"explication":"NE, SE, SO, NO."},{"txt":"Un vent de sud-ouest vient du nord-est.","vrai":false,"explication":"Il vient du sud-ouest."},{"txt":"La direction intermédiaire entre le nord et l'est s'appelle nord-est.","vrai":true,"explication":"On commence par nord ou sud."},{"txt":"La girouette mesure la vitesse du vent.","vrai":false,"explication":"L'anémomètre."},{"txt":"L'anémomètre est placé à 1,50 m du sol.","vrai":false,"explication":"À 10 m, en terrain dégagé."}],"consigne":"Keïta a noté six phrases sur la rose des vents et le vent. Pour chacune, réponds « Vrai » ou « Faux », puis choisis la phrase de la fiche qui donne le nom des directions intermédiaires.","indices":["La girouette indique la direction, l'anémomètre la vitesse.","On nomme un vent d'après sa provenance.","Le nom commence par nord ou sud."],"justification":{"question":"Quelle phrase de la fiche donne le nom des directions intermédiaires ?","options":["Elle porte les quatre points cardinaux (N, E, S, O) et les quatre directions intermédiaires (NE, SE, SO, NO).","Chaque direction intermédiaire prend le nom de ses deux voisines, en commençant par nord ou sud.","La girouette indique la direction d'où vient le vent : un vent de nord-ouest vient du nord-ouest.","L'Organisation météorologique mondiale demande de mesurer le vent à 10 m au-dessus d'un terrain dégagé, loin des obstacles, et de retenir la vitesse moyenne sur dix minutes."],"bonne":1},"dialogue":"Bonjour, matelots. Sur mon bateau, deux questions décident de tout : d'où vient le vent, et à quelle vitesse il souffle. La girouette répond à la première, l'anémomètre à la seconde. Mais sans les points cardinaux, une girouette ne sert à rien. Remettez la rose des vents dans le bon sens."}},{"id":"e2-2","escale":2,"ordre":2,"titre":"Girouette et anémomètre","decor":"mat","objet_principal":"objet-2","objets_cliquables":["objet-1","objet-2","objet-3","objet-4"],"personnage_emetteur":"keita","probleme_narratif":"Madame Vasseur vérifie ce que mesure chaque instrument.","enjeu":"Les confondre, c'est mal lire le vent.","episode_du_roman":"Organisation météorologique mondiale, Guide des instruments et des méthodes d'observation (OMM-N° 8) : vent mesuré à 10 m au-dessus d'un ter","competence_programme":"Utiliser les points cardinaux et la rose des vents","pourquoi_ce_savoir_ici":"La salle « Le mât du vent — direction et vitesse » repose sur cette notion.","reaction_du_decor":{"effet":"ouverture","description":"La girouette tourne face au vent."},"liberte_ou_anachronisme":"Aucune liberté particulière signalée (jeu migré).","lecon":"vent","type":"vraifaux","niveau_variantes":"Observateur (vraifaux) ; Releveur (vraifaux) ; Météorologue (vraifaux) ; Prévisionniste (tri) ; Climatologue (ordre). Mousse : indices renvoyant à la fiche, énoncés courts ; lieutenant et second : justification par une phrase de la fiche.","correction_origine":"La girouette indique la direction d'où vient le vent ; l'anémomètre mesure sa vitesse, en km/h ou en m/s. Un vent d'ouest vient de l'ouest. Pour être comparables, les mesures de vent se font à 10 m de haut, en terrain dégagé.","matelot":{"affirmations":[{"txt":"La girouette indique d'où vient le vent.","vrai":true,"explication":"Sa flèche pointe vers la direction d'où arrive le vent."},{"txt":"L'anémomètre mesure la vitesse du vent.","vrai":true,"explication":"Plus ses coupelles tournent vite, plus le vent est fort."},{"txt":"Un vent d'ouest souffle vers l'ouest.","vrai":false,"explication":"Un vent d'ouest vient de l'ouest et souffle vers l'est."},{"txt":"La vitesse du vent se mesure en degrés.","vrai":false,"explication":"Elle se mesure en kilomètres par heure (km/h) ou en mètres par seconde (m/s)."}],"consigne":"Pour chaque phrase, clique sur <b>Vrai</b> ou sur <b>Faux</b>, puis vérifie. Les lignes vertes sont justes : reprends seulement les autres.","indices":["Deux phrases sont vraies, deux sont fausses.","On nomme un vent d'après l'endroit d'où il vient, comme un voyageur d'après sa ville de départ.","Une vitesse se mesure en kilomètres par heure, comme pour une voiture."],"dialogue":"Girouette ou anémomètre ? Vrai ou faux."},"timonier":{"affirmations":[{"txt":"La girouette indique d'où vient le vent.","vrai":true,"explication":"Sa flèche pointe vers la direction d'où arrive le vent."},{"txt":"Un vent d'ouest souffle vers l'ouest.","vrai":false,"explication":"Un vent d'ouest vient de l'ouest et souffle vers l'est."},{"txt":"Mercredi, l'anémomètre indique 24 km/h : c'est une jolie brise, force 4 sur l'échelle de Beaufort.","vrai":true,"explication":"La force 4 correspond à un vent de 20 à 28 km/h."},{"txt":"Pour une mesure fiable, on place l'anémomètre au ras du sol, à l'abri des murs.","vrai":false,"explication":"On le place à 10 m de haut, en terrain dégagé, loin des obstacles."},{"txt":"Un vent de 1 m/s correspond à 3,6 km/h.","vrai":true,"explication":"En une heure (3 600 secondes), on parcourt 3 600 m, soit 3,6 km."},{"txt":"La rafale est la vitesse moyenne du vent sur dix minutes.","vrai":false,"explication":"La rafale est une pointe de vent, brève et plus forte que la moyenne."}],"consigne":"Pour chaque phrase, clique sur <b>Vrai</b> ou sur <b>Faux</b>, puis vérifie. Les lignes vertes sont justes : reprends seulement les autres.","indices":["Trois phrases sont vraies, trois sont fausses.","Au ras du sol, les murs et les arbres freinent le vent : la mesure serait faussée.","Une rafale, c'est un coup de vent bref, plus fort que la moyenne."],"dialogue":"Girouette ou anémomètre ? Vrai ou faux."},"mousse":{"type":"vraifaux","affirmations":[{"txt":"La girouette indique d'où vient le vent.","vrai":true,"explication":"Sa flèche pointe vers la direction d'où arrive le vent."},{"txt":"L'anémomètre mesure la vitesse du vent.","vrai":true,"explication":"Plus ses coupelles tournent vite, plus le vent est fort."},{"txt":"La vitesse du vent se mesure en degrés.","vrai":false,"explication":"En kilomètres par heure."}],"consigne":"Pour chaque phrase, clique sur « Vrai » ou sur « Faux », puis vérifie.","indices":["Ouvre la fiche « Mesurer le vent : direction et vitesse ».","La girouette montre la direction.","L'anémomètre mesure la vitesse."],"dialogue":"Voici mes affirmations. À vous de dire lesquelles sont vraies."},"lieutenant":{"type":"tri","colonnes":[{"id":"f2","titre":"Force 2 (6 à 11 km/h)"},{"id":"f4","titre":"Force 4 (20 à 28 km/h)"},{"id":"f6","titre":"Force 6 (39 à 49 km/h)"}],"cartes":[{"txt":"On sent le vent sur le visage","col":"f2"},{"txt":"Les feuilles frémissent","col":"f2"},{"txt":"La poussière se soulève","col":"f4"},{"txt":"Les petites branches bougent sans arrêt","col":"f4"},{"txt":"Les grosses branches s'agitent","col":"f6"},{"txt":"Le parapluie se tient mal","col":"f6"}],"consigne":"Keïta classe des vents selon leur force de Beaufort. Range chaque observation dans la bonne colonne, puis choisis la phrase de la fiche qui donne l'échelle de Beaufort.","indices":["Plus le vent est fort, plus les objets bougent.","Force 2 : sur le visage. Force 4 : la poussière. Force 6 : les grosses branches.","Relis l'échelle de la fiche."],"justification":{"question":"Quelle phrase de la fiche donne l'échelle de Beaufort ?","options":["L'Organisation météorologique mondiale demande de mesurer le vent à 10 m au-dessus d'un terrain dégagé, loin des obstacles, et de retenir la vitesse moyenne sur dix minutes.","Elle classe le vent de la force 0 (calme, moins de 1 km/h) à la force 12 (ouragan, 118 km/h et plus), d'après sa vitesse et ses effets : force 2 (6 à 11 km/h), on sent le vent sur le visage ; force 4 (20 à 28 km/h), la poussière se soulève ; force 6 (39 à 49 km/h), les grosses branches s'agitent.","L'anémomètre mesure sa vitesse, en km/h ou en mètres par seconde (1 m/s = 3,6 km/h, car une heure compte 3 600 secondes).","Elle porte les quatre points cardinaux (N, E, S, O) et les quatre directions intermédiaires (NE, SE, SO, NO)."],"bonne":1},"dialogue":"Il faut tout ranger. Placez chaque carte dans la bonne colonne."},"second":{"type":"ordre","items":[{"txt":"Calme : moins de 1 km/h","rang":1,"sous":"force 0"},{"txt":"Une brise de 5 m/s","rang":2,"sous":"environ 18 km/h"},{"txt":"Un vent de 10 m/s","rang":3,"sous":"36 km/h"},{"txt":"Un vent de 40 km/h","rang":4,"sous":"force 6"},{"txt":"Un ouragan","rang":5,"sous":"118 km/h et plus"}],"consigne":"Keïta range des vents du plus faible au plus fort (le plus faible en haut), puis choisis la phrase de la fiche qui explique la conversion des mètres par seconde en km/h.","indices":["1 m/s = 3,6 km/h.","5 m/s = 18 km/h ; 10 m/s = 36 km/h.","Force 6 : 39 à 49 km/h."],"justification":{"question":"Quelle phrase de la fiche explique la conversion des m/s en km/h ?","options":["Elle classe le vent de la force 0 (calme, moins de 1 km/h) à la force 12 (ouragan, 118 km/h et plus), d'après sa vitesse et ses effets : force 2 (6 à 11 km/h), on sent le vent sur le visage ; force 4 (20 à 28 km/h), la poussière se soulève ; force 6 (39 à 49 km/h), les grosses branches s'agitent.","L'Organisation météorologique mondiale demande de mesurer le vent à 10 m au-dessus d'un terrain dégagé, loin des obstacles, et de retenir la vitesse moyenne sur dix minutes.","L'anémomètre mesure sa vitesse, en km/h ou en mètres par seconde (1 m/s = 3,6 km/h, car une heure compte 3 600 secondes).","La girouette indique la direction d'où vient le vent : un vent de nord-ouest vient du nord-ouest."],"bonne":2},"dialogue":"Mes étapes sont mélangées. Remettez-les dans le bon ordre."}},{"id":"e2-3","escale":2,"ordre":3,"titre":"L'échelle de Beaufort","decor":"mat","objet_principal":"objet-3","objets_cliquables":["objet-1","objet-2","objet-3","objet-4"],"personnage_emetteur":"keita","probleme_narratif":"Tiago relie les effets du vent à l'échelle de Beaufort.","enjeu":"Sans l'échelle, on sous-estime la tempête.","episode_du_roman":"Échelle de Beaufort (Organisation météorologique mondiale) : vitesses en km/h et effets observés à terre","competence_programme":"Utiliser les points cardinaux et la rose des vents","pourquoi_ce_savoir_ici":"La salle « Le mât du vent — direction et vitesse » repose sur cette notion.","reaction_du_decor":{"effet":"lumiere","description":"Les arbres du fond se mettent à plier."},"liberte_ou_anachronisme":"Aucune liberté particulière signalée (jeu migré).","lecon":"vent","type":"association","niveau_variantes":"Observateur (association) ; Releveur (association) ; Météorologue (association) ; Prévisionniste (vraifaux) ; Climatologue (qcm). Mousse : indices renvoyant à la fiche, énoncés courts ; lieutenant et second : justification par une phrase de la fiche.","correction_origine":"L'échelle de Beaufort classe le vent de 0 (calme) à 12 (ouragan), d'après sa vitesse et ses effets visibles. Mercredi, à 24 km/h, le vent était de force 4 : une jolie brise.","matelot":{"paires":[{"g":"Calme : moins de 1 km/h","d":"La fumée monte tout droit."},{"g":"Légère brise : 6 à 11 km/h","d":"On sent le vent sur le visage, les feuilles frémissent."},{"g":"Jolie brise : 20 à 28 km/h (mercredi : 24 km/h)","d":"La poussière se soulève, les petites branches bougent sans arrêt."},{"g":"Vent frais : 39 à 49 km/h","d":"Les grosses branches s'agitent, le parapluie se tient mal."}],"consigne":"Le capitaine Keïta ne regarde pas toujours l'anémomètre : il observe la nature. Relie chaque vent (à gauche) à ce que l'on observe (à droite). Clique à gauche, puis à droite.","indices":["Plus le vent est rapide, plus les objets bougent.","Quand il n'y a pas de vent, la fumée monte tout droit.","Le vent de mercredi (24 km/h) soulève la poussière et agite les petites branches."],"dialogue":"Chaque force de vent a ses effets. Associez-les."},"timonier":{"paires":[{"g":"Force 0 · moins de 1 km/h","d":"La fumée monte verticalement."},{"g":"Force 2 · 6 à 11 km/h","d":"On sent le vent sur le visage, les feuilles frémissent."},{"g":"Force 4 · 20 à 28 km/h","d":"La poussière se soulève, les petites branches bougent sans arrêt."},{"g":"Force 6 · 39 à 49 km/h","d":"Les grosses branches s'agitent, les fils tendus sifflent."},{"g":"Force 12 · 118 km/h et plus","d":"Ouragan : des dégâts très importants."}],"consigne":"Relie chaque degré de l'échelle de Beaufort à ce que l'on observe à terre. Clique à gauche, puis à droite.","indices":["Force 0 : aucun mouvement. Force 12 : dégâts importants.","Force 2 : on sent le vent sur le visage.","Force 6 : les grosses branches s'agitent et le parapluie devient difficile à tenir."],"dialogue":"Chaque force de vent a ses effets. Associez-les."},"mousse":{"type":"association","paires":[{"g":"Calme","d":"la fumée monte tout droit"},{"g":"Légère brise","d":"on sent le vent sur le visage"},{"g":"Vent frais","d":"les grosses branches s'agitent"}],"consigne":"Le capitaine Keïta observe la nature. Relie chaque vent à ce que l'on observe. Clique à gauche, puis à droite.","indices":["Ouvre la fiche « Mesurer le vent : direction et vitesse ».","Plus le vent est rapide, plus les objets bougent.","Sans vent, la fumée monte tout droit."],"dialogue":"Il faut relier chaque élément à ce qui lui correspond."},"lieutenant":{"type":"vraifaux","affirmations":[{"txt":"On mesure le vent à 10 m, en terrain dégagé.","vrai":true,"explication":"Loin des obstacles."},{"txt":"On retient la vitesse moyenne sur dix minutes.","vrai":true,"explication":"Pour les mesures comparables."},{"txt":"Une rafale est une pointe de vent brève et plus forte.","vrai":true,"explication":"Plus forte que la moyenne."},{"txt":"1 m/s vaut 10 km/h.","vrai":false,"explication":"1 m/s = 3,6 km/h."},{"txt":"L'échelle de Beaufort va de 0 à 6.","vrai":false,"explication":"De 0 à 12."}],"consigne":"Keïta affirme cinq choses sur la mesure du vent. Pour chacune, réponds « Vrai » ou « Faux », puis choisis la phrase de la fiche qui définit la rafale.","indices":["10 m, terrain dégagé.","1 m/s = 3,6 km/h.","La rafale est brève."],"justification":{"question":"Quelle phrase de la fiche définit la rafale ?","options":["L'Organisation météorologique mondiale demande de mesurer le vent à 10 m au-dessus d'un terrain dégagé, loin des obstacles, et de retenir la vitesse moyenne sur dix minutes.","Une pointe brève et plus forte s'appelle une rafale.","L'anémomètre mesure sa vitesse, en km/h ou en mètres par seconde (1 m/s = 3,6 km/h, car une heure compte 3 600 secondes).","Elle classe le vent de la force 0 (calme, moins de 1 km/h) à la force 12 (ouragan, 118 km/h et plus), d'après sa vitesse et ses effets : force 2 (6 à 11 km/h), on sent le vent sur le visage ; force 4 (20 à 28 km/h), la poussière se soulève ; force 6 (39 à 49 km/h), les grosses branches s'agitent."],"bonne":1},"dialogue":"Voici mes affirmations. À vous de dire lesquelles sont vraies."},"second":{"type":"qcm","questions":[{"q":"Combien font 5 m/s en km/h ?","options":["18 km/h","5 km/h","8,6 km/h","50 km/h"],"bonne":0,"explication":"5 × 3,6 = 18."},{"q":"Combien font 14 m/s en km/h ?","options":["50,4 km/h","14 km/h","17,6 km/h","140 km/h"],"bonne":0,"explication":"14 × 3,6 = 50,4."},{"q":"Pourquoi 14 m/s est-ce une rafale et pas la vitesse moyenne ?","options":["C'est une pointe brève plus forte que la moyenne","C'est une vitesse constante","C'est la vitesse du son","Elle est mesurée au sol"],"bonne":0,"explication":"Une rafale est brève."}],"consigne":"<div class='doc-carnet'><b>Relevé de Keïta</b> (inventé pour le jeu). L'anémomètre indique 5 m/s, puis 14 m/s en rafale. Rappel : 1 m/s = 3,6 km/h.</div> Réponds aux trois questions, puis choisis la phrase de la fiche qui justifie la question 1.","indices":["Multiplie par 3,6.","14 × 3,6 : 14 × 3 = 42, puis 14 × 0,6 = 8,4.","La vitesse moyenne se calcule sur dix minutes."],"justification":{"question":"Quelle phrase de la fiche justifie ta réponse à la question 1 ?","options":["L'anémomètre mesure sa vitesse, en km/h ou en mètres par seconde (1 m/s = 3,6 km/h, car une heure compte 3 600 secondes).","L'Organisation météorologique mondiale demande de mesurer le vent à 10 m au-dessus d'un terrain dégagé, loin des obstacles, et de retenir la vitesse moyenne sur dix minutes.","Une pointe brève et plus forte s'appelle une rafale.","La girouette indique la direction d'où vient le vent : un vent de nord-ouest vient du nord-ouest."],"bonne":0},"dialogue":"J'ai quelques questions pour vous. Lisez bien le document avant de répondre."}},{"id":"e2-4","escale":2,"ordre":4,"titre":"Le carnet du capitaine","decor":"mat","objet_principal":"objet-4","objets_cliquables":["objet-1","objet-2","objet-3","objet-4"],"personnage_emetteur":"keita","probleme_narratif":"Lina complète le carnet du capitaine.","enjeu":"Sans carnet, on ne sait plus d'où soufflait le vent.","episode_du_roman":"Organisation météorologique mondiale, Guide des instruments et des méthodes d'observation (OMM-N° 8) : vent mesuré à 10 m au-dessus d'un ter","competence_programme":"Utiliser les points cardinaux et la rose des vents","pourquoi_ce_savoir_ici":"La salle « Le mât du vent — direction et vitesse » repose sur cette notion.","reaction_du_decor":{"effet":"eclat","description":"Le carnet s'ouvre sur une carte des vents."},"liberte_ou_anachronisme":"Aucune liberté particulière signalée (jeu migré).","lecon":"vent","type":"trous","niveau_variantes":"Météorologue (trous) ; Prévisionniste (trous) ; Climatologue (trous). Mousse : indices renvoyant à la fiche, énoncés courts ; lieutenant et second : justification par une phrase de la fiche.","correction_origine":"La girouette donne la direction d'où vient le vent, l'anémomètre sa vitesse. On les installe à 10 m au-dessus d'un terrain dégagé. La vitesse retenue est une moyenne sur dix minutes ; une pointe brève et plus forte s'appelle une rafale.","niveaux":["timonier","lieutenant","second"],"timonier":{"texte":"La girouette indique la [[direction]] d'où vient le vent ; l'[[anémomètre]] mesure sa [[vitesse]]. Pour que les mesures soient comparables partout dans le monde, on installe ces instruments à [[10 m]] au-dessus d'un terrain dégagé. On retient la vitesse moyenne sur dix minutes ; un coup de vent bref et plus fort s'appelle une [[rafale]].","etiquettes":["direction","anémomètre","vitesse","10 m","rafale","1,50 m","pluviomètre","température"],"consigne":"Complète le carnet du capitaine Keïta : clique sur une étiquette, puis sur le trou. Attention, certaines étiquettes ne servent à rien.","indices":["Deux instruments : l'un pour la direction, l'autre pour la vitesse.","1,50 m, c'est la hauteur du thermomètre, pas celle de l'anémomètre.","Le mot qui manque à la fin désigne un coup de vent bref et fort."],"dialogue":"Voici le carnet du capitaine. Complétez-le."},"lieutenant":{"type":"trous","texte":"<p>La girouette indique la [[direction]] d'où vient le vent ; l'anémomètre mesure sa [[vitesse]]. On installe les instruments à [[10 m]] de haut, en terrain [[dégagé]]. Une pointe brève et plus forte s'appelle une [[rafale]].</p>","etiquettes":["direction","vitesse","10 m","dégagé","rafale","1,50 m","pluviomètre","température"],"consigne":"Keïta a rédigé son carnet, mais il manque des mots. Clique sur une étiquette, puis sur le trou où elle va. Trois étiquettes sont en trop. Puis choisis la phrase de la fiche qui justifie le mot « 10 m ».","indices":["Deux instruments : l'un pour la direction, l'autre pour la vitesse.","1,50 m est la hauteur du thermomètre.","Un coup de vent bref s'appelle une rafale."],"justification":{"question":"Quelle phrase de la fiche justifie le mot « 10 m » ?","options":["La girouette indique la direction d'où vient le vent : un vent de nord-ouest vient du nord-ouest.","L'Organisation météorologique mondiale demande de mesurer le vent à 10 m au-dessus d'un terrain dégagé, loin des obstacles, et de retenir la vitesse moyenne sur dix minutes.","Une pointe brève et plus forte s'appelle une rafale.","L'anémomètre mesure sa vitesse, en km/h ou en mètres par seconde (1 m/s = 3,6 km/h, car une heure compte 3 600 secondes)."],"bonne":1},"dialogue":"Il manque des mots dans mon carnet. Remettez-les à leur place."},"second":{"type":"trous","texte":"<p>L'échelle de Beaufort classe le vent de la force [[0]] (calme) à la force [[12]] (ouragan, 118 km/h et plus). À la force 4, la [[poussière]] se soulève ; à la force 6, les grosses [[branches]] s'agitent.</p>","etiquettes":["0","12","poussière","branches","ouragan","9","pluie","feuilles","neige"],"consigne":"Keïta résume l'échelle de Beaufort, mais il manque des mots. Clique sur une étiquette, puis sur le trou où elle va. Quatre étiquettes sont en trop. Puis choisis la phrase de la fiche qui justifie le mot « ouragan ».","indices":["Les deux extrémités de l'échelle : 0 et 12.","Force 4 : la poussière.","Force 6 : les grosses branches."],"justification":{"question":"Quelle phrase de la fiche justifie le mot « ouragan » ?","options":["L'anémomètre mesure sa vitesse, en km/h ou en mètres par seconde (1 m/s = 3,6 km/h, car une heure compte 3 600 secondes).","L'Organisation météorologique mondiale demande de mesurer le vent à 10 m au-dessus d'un terrain dégagé, loin des obstacles, et de retenir la vitesse moyenne sur dix minutes.","Elle classe le vent de la force 0 (calme, moins de 1 km/h) à la force 12 (ouragan, 118 km/h et plus), d'après sa vitesse et ses effets : force 2 (6 à 11 km/h), on sent le vent sur le visage ; force 4 (20 à 28 km/h), la poussière se soulève ; force 6 (39 à 49 km/h), les grosses branches s'agitent.","Elle porte les quatre points cardinaux (N, E, S, O) et les quatre directions intermédiaires (NE, SE, SO, NO)."],"bonne":2},"dialogue":"Il manque des mots dans mon carnet. Remettez-les à leur place."}}]},{"numero":3,"id":"le-pluviometre-mesurer-la-pluie","titre":"Le pluviomètre","lieu":"🌧️ Le pluviomètre, au fond du jardin","matiere":"","periode_conseillee":"","episode":"Loin des arbres et des murs, un entonnoir surmonte un tube gradué. Il pleut encore un peu. Sur le cahier de Tiago, les relevés de la semaine sont brouillés par les gouttes.","scenarimage":"","mot":"CUMULER","mot_origine":"Le mot-clé de la salle 3.","air":null,"cinematique_ouverture":"transition-e3","cinematique_fin":"fin-e3","etats_decor":[],"enigmes":[{"id":"e3-1","escale":3,"ordre":1,"titre":"Lire le pluviomètre","decor":"pluvio","objet_principal":"objet-1","objets_cliquables":["objet-1","objet-2","objet-3","objet-4"],"personnage_emetteur":"tiago","probleme_narratif":"Tiago attend la lecture du pluviomètre.","enjeu":"Une mauvaise lecture fausse le cumul de pluie.","episode_du_roman":"Fondation La main à la pâte, « Construire quelques instruments d'une station météorologique » (cycle 3) ; Relevés de la station fictive de l","competence_programme":"Lire la hauteur d'eau d'un pluviomètre","pourquoi_ce_savoir_ici":"La salle « Le pluviomètre — mesurer la pluie » repose sur cette notion.","reaction_du_decor":{"effet":"ouverture","description":"L'eau monte dans le pluviomètre."},"liberte_ou_anachronisme":"Aucune liberté particulière signalée (jeu migré).","lecon":"pluie","type":"instrument","niveau_variantes":"Observateur (instrument) ; Releveur (instrument) ; Météorologue (instrument) ; Prévisionniste (instrument) ; Climatologue (instrument). Mousse : indices renvoyant à la fiche, énoncés courts ; lieutenant et second : justification par une phrase de la fiche.","correction_origine":"On lit la graduation qui touche le haut de l'eau, les yeux bien en face. Mercredi, le pluviomètre indiquait 7 mm de pluie tombée en 24 heures.","matelot":{"instrument":"pluviometre","unite":"mm","min":0,"max":20,"pas":1,"etiquettes":5,"items":[{"libelle":"Mardi matin","mode":"lire","valeur":3},{"libelle":"Mercredi matin","mode":"lire","valeur":7},{"libelle":"Jeudi matin","mode":"lire","valeur":12}],"consigne":"Voici trois relevés du pluviomètre, lus chaque matin. Regarde le haut de l'eau, compte les graduations et écris la hauteur de pluie en <b>millimètres</b>. Une petite graduation vaut <b>1 mm</b>.","indices":["Les grands traits portent 0, 5, 10, 15 et 20.","Pars du grand trait juste en dessous de l'eau et compte les petits traits en montant.","Le relevé de mercredi est entre 5 et 10 mm, deux graduations au-dessus du 5."],"dialogue":"Salut ! Le pluviomètre recueille la pluie qui tombe sur son ouverture. On ne compte pas des litres : on lit une hauteur d'eau, en millimètres. Chaque matin, on lit, on note, on vide. Et en additionnant les jours, on obtient le cumul. À toi de lire le tube."},"timonier":{"instrument":"pluviometre","unite":"mm","min":0,"max":20,"pas":0.5,"etiquettes":5,"items":[{"libelle":"Mercredi matin","mode":"lire","valeur":7},{"libelle":"Jeudi matin","mode":"lire","valeur":12},{"libelle":"Pluviomètre du jardin partagé","mode":"lire","valeur":4.5},{"libelle":"Règle : 9,5 mm","mode":"regler","valeur":9.5,"depart":5}],"consigne":"Lis les trois premiers pluviomètres. Ici, une petite graduation vaut <b>0,5 mm</b> : écris la hauteur avec une virgule si besoin. Pour le quatrième, règle le niveau d'eau avec ▲ et ▼ (ou clique sur l'échelle).","indices":["Entre deux grands traits (5 mm), il y a 10 petites graduations : chacune vaut 0,5 mm.","Deux petites graduations font 1 mm.","Pour 9,5 mm : un petit trait sous le 10."],"dialogue":"Salut ! Le pluviomètre recueille la pluie qui tombe sur son ouverture. On ne compte pas des litres : on lit une hauteur d'eau, en millimètres. Chaque matin, on lit, on note, on vide. Et en additionnant les jours, on obtient le cumul. À toi de lire le tube."},"mousse":{"type":"instrument","instrument":"pluviometre","unite":"mm","min":0,"max":20,"pas":1,"etiquettes":5,"items":[{"libelle":"Mardi matin","mode":"lire","valeur":4},{"libelle":"Mercredi matin","mode":"lire","valeur":9}],"consigne":"Voici deux relevés du pluviomètre. Regarde le haut de l'eau et écris la hauteur de pluie en <b>millimètres</b>. Une petite graduation vaut <b>1 mm</b>.","indices":["Ouvre la fiche « Mesurer la pluie avec un pluviomètre » dans la Bibliothèque.","Les grands traits portent 0, 5, 10, 15 et 20.","Compte les petits traits au-dessus du grand trait."],"dialogue":"Salut ! Le pluviomètre recueille la pluie qui tombe sur son ouverture. On ne compte pas des litres : on lit une hauteur d'eau, en millimètres. Chaque matin, on lit, on note, on vide. Et en additionnant les jours, on obtient le cumul. À toi de lire le tube."},"lieutenant":{"type":"instrument","instrument":"pluviometre","unite":"mm","min":0,"max":20,"pas":0.5,"etiquettes":5,"items":[{"libelle":"Lundi matin","mode":"lire","valeur":6.5},{"libelle":"Mardi matin","mode":"lire","valeur":11},{"libelle":"Règle : 14,5 mm","mode":"regler","valeur":14.5,"depart":10}],"consigne":"Lis les deux premiers pluviomètres. Ici, une petite graduation vaut <b>0,5 mm</b>. Pour le troisième, règle le niveau d'eau avec ▲ et ▼. Puis choisis la phrase de la fiche qui définit ce que mesure un pluviomètre.","indices":["Entre deux grands traits (5 mm), il y a 10 petites graduations.","Deux petites graduations font 1 mm.","14,5 mm : un petit trait sous le 15."],"justification":{"question":"Quelle phrase de la fiche définit ce que mesure un pluviomètre ?","options":["1 mm sur 1 m² = 1 litre, car 1 mm × 1 m² = 1 dm³.","Le pluviomètre mesure la hauteur de précipitations, en millimètres : c'est l'épaisseur de la couche d'eau qui couvrirait un sol plat si rien ne s'écoulait ni ne s'évaporait.","On le place en terrain dégagé : un arbre ou un mur arrête ou renvoie la pluie.","Le cumul est la somme des hauteurs relevées sur une période : semaine, mois, année."],"bonne":1},"dialogue":"Salut ! Le pluviomètre recueille la pluie qui tombe sur son ouverture. On ne compte pas des litres : on lit une hauteur d'eau, en millimètres. Chaque matin, on lit, on note, on vide. Et en additionnant les jours, on obtient le cumul. À toi de lire le tube."},"second":{"type":"instrument","instrument":"pluviometre","unite":"mm","min":0,"max":30,"pas":0.5,"etiquettes":5,"items":[{"libelle":"Un jour d'orage","mode":"lire","valeur":18.5},{"libelle":"La semaine d'automne","mode":"lire","valeur":23},{"libelle":"Règle : 27,5 mm","mode":"regler","valeur":27.5,"depart":20}],"consigne":"Lis les deux premiers pluviomètres : ici, une petite graduation vaut <b>0,5 mm</b>. Pour le troisième, règle le niveau d'eau avec ▲ et ▼. Puis choisis la phrase de la fiche qui explique pourquoi on lit le pluviomètre à heure fixe.","indices":["Entre deux grands traits (5 mm), il y a 10 petites graduations.","23 mm : trois grands traits et demi.","27,5 mm : un petit trait sous le 28."],"justification":{"question":"Quelle phrase de la fiche explique pourquoi on lit à heure fixe ?","options":["Le pluviomètre mesure la hauteur de précipitations, en millimètres : c'est l'épaisseur de la couche d'eau qui couvrirait un sol plat si rien ne s'écoulait ni ne s'évaporait.","Pour connaître le volume tombé sur une surface, on multiplie : 7 mm sur une cour de 200 m² font 7 × 200 = 1 400 litres.","On le lit à heure fixe (souvent le matin, pour les 24 heures écoulées), puis on le vide ; sinon, on lirait la somme de plusieurs jours.","Il permet de comparer des périodes ou des lieux."],"bonne":2},"dialogue":"Salut ! Le pluviomètre recueille la pluie qui tombe sur son ouverture. On ne compte pas des litres : on lit une hauteur d'eau, en millimètres. Chaque matin, on lit, on note, on vide. Et en additionnant les jours, on obtient le cumul. À toi de lire le tube."}},{"id":"e3-2","escale":3,"ordre":2,"titre":"Un millimètre de pluie","decor":"pluvio","objet_principal":"objet-2","objets_cliquables":["objet-1","objet-2","objet-3","objet-4"],"personnage_emetteur":"tiago","probleme_narratif":"Lina cherche ce que veut dire un millimètre de pluie.","enjeu":"Sans comprendre le millimètre, on ne compare rien.","episode_du_roman":"Eaufrance, « Les volumes de précipitations » : une hauteur de 1 mm correspond à 1 litre d'eau par mètre carré ; Fondation La main à la pâte,","competence_programme":"Lire la hauteur d'eau d'un pluviomètre","pourquoi_ce_savoir_ici":"La salle « Le pluviomètre — mesurer la pluie » repose sur cette notion.","reaction_du_decor":{"effet":"lumiere","description":"Quelques gouttes tombent sur la jauge."},"liberte_ou_anachronisme":"Aucune liberté particulière signalée (jeu migré).","lecon":"pluie","type":"qcm","niveau_variantes":"Observateur (qcm) ; Releveur (qcm) ; Météorologue (qcm) ; Prévisionniste (vraifaux) ; Climatologue (qcm). Mousse : indices renvoyant à la fiche, énoncés courts ; lieutenant et second : justification par une phrase de la fiche.","correction_origine":"Une hauteur de 1 mm d'eau sur une surface de 1 m² représente 1 litre (1 mm × 1 m² = 1 dm³). Le pluviomètre s'installe dans un endroit dégagé, loin des arbres et des murs, et on le vide après chaque lecture.","matelot":{"questions":[{"q":"Dans quelle unité lit-on une hauteur de pluie ?","options":["en millimètres (mm)","en degrés (°C)","en kilomètres par heure (km/h)"],"bonne":0,"explication":"On mesure la hauteur d'eau tombée, comme avec une règle."},{"q":"Où installe-t-on le pluviomètre ?","options":["dans un endroit dégagé, loin des arbres et des murs","sous un arbre, pour le protéger","sous le préau"],"bonne":0,"explication":"Rien ne doit arrêter la pluie avant qu'elle entre dans le pluviomètre."},{"q":"1 mm de pluie, cela représente…","options":["1 litre d'eau sur chaque mètre carré","1 litre d'eau pour toute la cour","une seule goutte"],"bonne":0,"explication":"Mercredi, avec 7 mm, il est tombé 7 litres d'eau sur chaque mètre carré."}],"consigne":"Tiago te pose trois questions sur son pluviomètre. Choisis une réponse par question, puis vérifie.","indices":["La règle graduée du pluviomètre est la même que celle de ta règle : des millimètres.","Sous un arbre, les feuilles arrêtent une partie de la pluie.","1 mm de pluie sur un carré d'un mètre de côté remplit une bouteille d'un litre."],"dialogue":"Un millimètre de pluie, qu'est-ce que c'est ? Répondez."},"timonier":{"questions":[{"q":"Pourquoi Tiago vide-t-il le pluviomètre chaque matin, après la lecture ?","options":["pour mesurer la pluie de chaque journée séparément","pour que l'eau ne gèle pas","pour arroser le jardin","parce que le tube est trop petit"],"bonne":0,"explication":"Sinon, la pluie des jours précédents s'ajouterait : on lirait un cumul, pas la pluie du jour."},{"q":"Pourquoi ne faut-il pas installer le pluviomètre près d'un mur ?","options":["le mur peut arrêter la pluie ou la renvoyer vers le tube","le mur réchauffe l'eau","le mur fait peur aux oiseaux","le mur empêche de lire"],"bonne":0,"explication":"Un obstacle proche fausse la quantité d'eau recueillie, en plus ou en moins."},{"q":"La cour mesure 200 m². Mercredi, il est tombé 7 mm. Combien de litres d'eau sont tombés sur la cour ?","options":["1 400 litres","207 litres","7 litres","140 litres"],"bonne":0,"explication":"7 mm = 7 litres par mètre carré ; 7 × 200 = 1 400 litres."}],"consigne":"Réponds aux trois questions. Pour la dernière, un calcul est nécessaire : pose-le au brouillon.","indices":["Si on ne vide pas le tube, la pluie de mardi s'ajoute à celle de mercredi.","1 mm sur 1 m² = 1 litre. 7 mm sur 1 m² = 7 litres.","Sur 200 m², il faut multiplier par 200 : 7 × 200."],"dialogue":"Un millimètre de pluie, qu'est-ce que c'est ? Répondez."},"mousse":{"type":"qcm","questions":[{"q":"Dans quelle unité lit-on une hauteur de pluie ?","options":["en millimètres (mm)","en degrés (°C)","en kilomètres par heure (km/h)"],"bonne":0,"explication":"On mesure une hauteur d'eau."}],"consigne":"Tiago te pose une question sur son pluviomètre. Clique sur la bonne réponse, puis vérifie.","indices":["Ouvre la fiche « Mesurer la pluie avec un pluviomètre ».","La règle graduée est en millimètres.","Les degrés mesurent la température."],"dialogue":"J'ai quelques questions pour vous. Lisez bien le document avant de répondre."},"lieutenant":{"type":"vraifaux","affirmations":[{"txt":"1 mm de pluie sur 1 m² représente 1 litre.","vrai":true,"explication":"1 mm × 1 m² = 1 dm³."},{"txt":"Le pluviomètre se place sous un arbre pour le protéger.","vrai":false,"explication":"Un arbre arrête la pluie."},{"txt":"On le lit à heure fixe, puis on le vide.","vrai":true,"explication":"Sinon, on lirait la somme de plusieurs jours."},{"txt":"Le pluviomètre mesure la température.","vrai":false,"explication":"Il mesure la hauteur de pluie."},{"txt":"5 mm de pluie sur 10 m² font 50 litres.","vrai":true,"explication":"5 × 10 = 50."}],"consigne":"Tiago a noté cinq phrases sur la pluie. Pour chacune, réponds « Vrai » ou « Faux », puis choisis la phrase de la fiche qui donne l'équivalent de 1 mm en litres.","indices":["1 mm = 1 litre par m².","Un arbre ou un mur fausse la mesure.","Pour la justification : cherche la phrase avec « 1 dm³ »."],"justification":{"question":"Quelle phrase de la fiche donne l'équivalent de 1 mm en litres ?","options":["Le pluviomètre mesure la hauteur de précipitations, en millimètres : c'est l'épaisseur de la couche d'eau qui couvrirait un sol plat si rien ne s'écoulait ni ne s'évaporait.","1 mm sur 1 m² = 1 litre, car 1 mm × 1 m² = 1 dm³.","Pour connaître le volume tombé sur une surface, on multiplie : 7 mm sur une cour de 200 m² font 7 × 200 = 1 400 litres.","On le lit à heure fixe (souvent le matin, pour les 24 heures écoulées), puis on le vide ; sinon, on lirait la somme de plusieurs jours."],"bonne":1},"dialogue":"Voici mes affirmations. À vous de dire lesquelles sont vraies."},"second":{"type":"qcm","questions":[{"q":"Combien de litres tombent sur 1 m² ?","options":["4,5 litres","45 litres","0,45 litre","4 litres"],"bonne":0,"explication":"1 mm = 1 litre par m²."},{"q":"Combien de litres tombent sur la cour de 200 m² ?","options":["900 litres","200 litres","450 litres","9 000 litres"],"bonne":0,"explication":"4,5 × 200 = 900."},{"q":"Pourquoi vide-t-on le pluviomètre après la lecture ?","options":["Pour ne pas additionner la pluie de plusieurs jours","Pour arroser les plantes","Pour éviter le gel","Parce qu'il est plein"],"bonne":0,"explication":"Sinon on lirait une somme."}],"consigne":"<div class='doc-carnet'><b>Relevé de la cour</b> (inventé pour le jeu). Un matin, le pluviomètre indique 4,5 mm. La cour de l'école mesure 200 m². Rappel : 1 mm sur 1 m² = 1 litre.</div> Réponds aux trois questions, puis choisis la phrase de la fiche qui justifie la question 1.","indices":["1 mm sur 1 m² : 1 litre.","Multiplie 4,5 par 200.","Le pluviomètre se lit à heure fixe, puis se vide."],"justification":{"question":"Quelle phrase de la fiche justifie ta réponse à la question 1 ?","options":["Pour connaître le volume tombé sur une surface, on multiplie : 7 mm sur une cour de 200 m² font 7 × 200 = 1 400 litres.","On le lit à heure fixe (souvent le matin, pour les 24 heures écoulées), puis on le vide ; sinon, on lirait la somme de plusieurs jours.","1 mm sur 1 m² = 1 litre, car 1 mm × 1 m² = 1 dm³.","Le cumul est la somme des hauteurs relevées sur une période : semaine, mois, année."],"bonne":2},"dialogue":"J'ai quelques questions pour vous. Lisez bien le document avant de répondre."}},{"id":"e3-3","escale":3,"ordre":3,"titre":"Du plus sec au plus arrosé","decor":"pluvio","objet_principal":"objet-3","objets_cliquables":["objet-1","objet-2","objet-3","objet-4"],"personnage_emetteur":"tiago","probleme_narratif":"Keita range les journées par quantité de pluie.","enjeu":"Sans l'ordre, le bilan des pluies est faux.","episode_du_roman":"Eaufrance, « Les volumes de précipitations » : une hauteur de 1 mm correspond à 1 litre d'eau par mètre carré ; Relevés de la station fictiv","competence_programme":"Lire la hauteur d'eau d'un pluviomètre","pourquoi_ce_savoir_ici":"La salle « Le pluviomètre — mesurer la pluie » repose sur cette notion.","reaction_du_decor":{"effet":"eclat","description":"Les nuages défilent sur le tableau."},"liberte_ou_anachronisme":"Aucune liberté particulière signalée (jeu migré).","lecon":"pluie","type":"ordre","niveau_variantes":"Observateur (ordre) ; Releveur (ordre) ; Météorologue (ordre) ; Prévisionniste (ordre) ; Climatologue (ordre). Mousse : indices renvoyant à la fiche, énoncés courts ; lieutenant et second : justification par une phrase de la fiche.","correction_origine":"Pour comparer des pluies, on compare leurs hauteurs en millimètres. Comme 1 L/m² = 1 mm, 7 litres tombés sur 1 m² font 7 mm, et 15 litres sur 1 m² font 15 mm.","matelot":{"items":[{"txt":"Lundi : 0 mm","rang":1},{"txt":"Mardi : 3 mm","rang":2},{"txt":"Mercredi : 7 mm","rang":3},{"txt":"Jeudi : 12 mm","rang":4}],"consigne":"Range les jours <b>du plus sec (en haut) au plus arrosé (en bas)</b>.","indices":["Le jour le plus sec est celui où il n'est pas tombé une goutte.","Compare 3, 7 et 12.","Le plus arrosé est jeudi."],"dialogue":"Du plus sec au plus arrosé : rangez les journées."},"timonier":{"items":[{"txt":"Une bruine : 0,5 mm","rang":1},{"txt":"Mardi : 3 mm","rang":2},{"txt":"Mercredi : 7 litres tombés sur 1 m²","rang":3},{"txt":"Jeudi : 12 mm","rang":4},{"txt":"Un orage d'été : 15 litres tombés sur 1 m²","rang":5}],"consigne":"Range ces pluies <b>de la plus faible (en haut) à la plus forte (en bas)</b>. Certaines sont données en litres par mètre carré : convertis-les d'abord en millimètres.","indices":["7 litres sur 1 m² = 7 mm ; 15 litres sur 1 m² = 15 mm.","0,5 mm est plus petit que 3 mm.","Ordre attendu : 0,5 ; 3 ; 7 ; 12 ; 15."],"dialogue":"Du plus sec au plus arrosé : rangez les journées."},"mousse":{"type":"ordre","items":[{"txt":"Lundi : 0 mm","rang":1},{"txt":"Mardi : 4 mm","rang":2},{"txt":"Mercredi : 9 mm","rang":3}],"consigne":"Range les jours du plus sec (en haut) au plus arrosé (en bas) avec les flèches ▲ ▼.","indices":["Ouvre la fiche « Mesurer la pluie avec un pluviomètre ».","Le jour le plus sec n'a pas de pluie.","9 est le plus grand."],"dialogue":"Mes étapes sont mélangées. Remettez-les dans le bon ordre."},"lieutenant":{"type":"ordre","items":[{"txt":"Une bruine : 1 mm","rang":1},{"txt":"Mardi : 4,5 mm","rang":2},{"txt":"Mercredi : 8 litres tombés sur 1 m²","rang":3},{"txt":"Jeudi : 11 mm","rang":4},{"txt":"Un orage : 20 litres tombés sur 1 m²","rang":5}],"consigne":"Tiago range des pluies, parfois données en litres par mètre carré. Convertis-les en millimètres, puis range-les de la plus faible (en haut) à la plus forte (en bas). Puis choisis la phrase de la fiche qui justifie la conversion.","indices":["8 litres sur 1 m² = 8 mm.","20 litres sur 1 m² = 20 mm.","Ordre : 1 ; 4,5 ; 8 ; 11 ; 20."],"justification":{"question":"Quelle phrase de la fiche justifie la conversion litres par m² en mm ?","options":["1 mm sur 1 m² = 1 litre, car 1 mm × 1 m² = 1 dm³.","Le pluviomètre mesure la hauteur de précipitations, en millimètres : c'est l'épaisseur de la couche d'eau qui couvrirait un sol plat si rien ne s'écoulait ni ne s'évaporait.","Pour connaître le volume tombé sur une surface, on multiplie : 7 mm sur une cour de 200 m² font 7 × 200 = 1 400 litres.","Le cumul est la somme des hauteurs relevées sur une période : semaine, mois, année."],"bonne":0},"dialogue":"Mes étapes sont mélangées. Remettez-les dans le bon ordre."},"second":{"type":"ordre","items":[{"txt":"3 mm sur 10 m² : 30 litres","rang":1},{"txt":"5 mm sur 10 m² : 50 litres","rang":2},{"txt":"2 mm sur 100 m² : 200 litres","rang":3},{"txt":"7 mm sur 100 m² : 700 litres","rang":4},{"txt":"7 mm sur 200 m² : 1 400 litres","rang":5}],"consigne":"Tiago range des pluies en mm et en litres sur des surfaces différentes. Pour chacune, calcule le nombre de litres, puis range de la plus petite (en haut) à la plus grande quantité d'eau (en bas), puis choisis la phrase de la fiche qui donne la méthode.","indices":["Multiplie les mm par les m².","30 ; 50 ; 200 ; 700 ; 1 400.","1 mm sur 1 m² = 1 litre."],"justification":{"question":"Quelle phrase de la fiche donne la méthode de calcul ?","options":["1 mm sur 1 m² = 1 litre, car 1 mm × 1 m² = 1 dm³.","Le pluviomètre mesure la hauteur de précipitations, en millimètres : c'est l'épaisseur de la couche d'eau qui couvrirait un sol plat si rien ne s'écoulait ni ne s'évaporait.","Pour connaître le volume tombé sur une surface, on multiplie : 7 mm sur une cour de 200 m² font 7 × 200 = 1 400 litres.","Le cumul est la somme des hauteurs relevées sur une période : semaine, mois, année."],"bonne":2},"dialogue":"Mes étapes sont mélangées. Remettez-les dans le bon ordre."}},{"id":"e3-4","escale":3,"ordre":4,"titre":"Le cadenas du cumul","decor":"pluvio","objet_principal":"objet-4","objets_cliquables":["objet-1","objet-2","objet-3","objet-4"],"personnage_emetteur":"tiago","probleme_narratif":"Madame Vasseur a caché le code dans les relevés.","enjeu":"Sans le bon cumul, le cadenas reste fermé.","episode_du_roman":"Eaufrance, « Les volumes de précipitations » : une hauteur de 1 mm correspond à 1 litre d'eau par mètre carré ; Relevés de la station fictiv","competence_programme":"Lire la hauteur d'eau d'un pluviomètre","pourquoi_ce_savoir_ici":"La salle « Le pluviomètre — mesurer la pluie » repose sur cette notion.","reaction_du_decor":{"effet":"calme","description":"Le cadenas s'ouvre."},"liberte_ou_anachronisme":"Aucune liberté particulière signalée (jeu migré).","lecon":"pluie","type":"code","niveau_variantes":"Météorologue (code) ; Prévisionniste (code) ; Climatologue (code). Mousse : indices renvoyant à la fiche, énoncés courts ; lieutenant et second : justification par une phrase de la fiche.","correction_origine":"Le cumul est la somme des hauteurs : 0 + 3 + 7 + 12 + 0 = 22 mm. Mercredi, 7 mm sur 10 m² : 7 × 10 = 70 litres.","niveaux":["timonier","lieutenant","second"],"timonier":{"champs":[{"libelle":"Cumul de la semaine (en mm)","valeur":"22","longueur":3},{"libelle":"Litres tombés mercredi sur le potager de 10 m²","valeur":"70","longueur":4}],"consigne":"Le cahier de Tiago indique pour la semaine : lundi 0 mm, mardi 3 mm, mercredi 7 mm, jeudi 12 mm, vendredi 0 mm. Ouvre le cadenas avec deux nombres.","indices":["Cumuler, c'est additionner les pluies de tous les jours.","0 + 3 + 7 + 12 + 0 = ?","1 mm = 1 litre par mètre carré ; le potager fait 10 m²."],"dialogue":"Additionnez les pluies pour trouver le code."},"lieutenant":{"type":"code","champs":[{"libelle":"Cumul de la semaine (en mm)","valeur":"20","longueur":3},{"libelle":"Litres tombés mercredi sur 15 m²","valeur":"75","longueur":3}],"consigne":"Le cahier de Tiago indique pour la semaine : lundi 2 mm, mardi 0 mm, mercredi 5 mm, jeudi 9 mm, vendredi 4 mm. Ouvre le cadenas avec deux nombres : le cumul de la semaine et le nombre de litres tombés mercredi sur un potager de 15 m².","indices":["Cumuler, c'est additionner : 2 + 0 + 5 + 9 + 4.","5 mm = 5 litres par m².","5 × 15."],"justification":{"question":"Quelle phrase de la fiche définit le cumul ?","options":["1 mm sur 1 m² = 1 litre, car 1 mm × 1 m² = 1 dm³.","Le cumul est la somme des hauteurs relevées sur une période : semaine, mois, année.","Il permet de comparer des périodes ou des lieux.","Pour connaître le volume tombé sur une surface, on multiplie : 7 mm sur une cour de 200 m² font 7 × 200 = 1 400 litres."],"bonne":1},"dialogue":"Ce cadenas ne s'ouvre qu'avec le bon code. Lisez bien le document."},"second":{"type":"code","champs":[{"libelle":"Cumul de la semaine (en mm)","valeur":"21","longueur":3},{"libelle":"Litres tombés jeudi sur 40 m²","valeur":"420","longueur":4}],"consigne":"Le cahier de Tiago indique pour la semaine : lundi 1,5 mm, mardi 0 mm, mercredi 6 mm, jeudi 10,5 mm, vendredi 3 mm. Ouvre le cadenas avec deux nombres : le cumul de la semaine en mm et le nombre de litres tombés jeudi sur un terrain de 40 m².","indices":["Additionne : 1,5 + 0 + 6 + 10,5 + 3.","10,5 mm = 10,5 litres par m².","10,5 × 40."],"justification":{"question":"Quelle phrase de la fiche explique à quoi sert le cumul ?","options":["Il permet de comparer des périodes ou des lieux.","Le cumul est la somme des hauteurs relevées sur une période : semaine, mois, année.","1 mm sur 1 m² = 1 litre, car 1 mm × 1 m² = 1 dm³.","Pour connaître le volume tombé sur une surface, on multiplie : 7 mm sur une cour de 200 m² font 7 × 200 = 1 400 litres."],"bonne":0},"dialogue":"Ce cadenas ne s'ouvre qu'avec le bon code. Lisez bien le document."}}]},{"numero":4,"id":"le-tableau-des-releves-organiser-et-exploiter","titre":"Le tableau des relevés","lieu":"📋 Le bureau des relevés","matiere":"","periode_conseillee":"","episode":"Au mur, un tableau à double entrée et un graphique en barres. L'eau a effacé des cases, et quelqu'un a recopié une valeur impossible.","scenarimage":"","mot":"ORGANISER","mot_origine":"Le mot-clé de la salle 4.","air":null,"cinematique_ouverture":"transition-e4","cinematique_fin":"fin-e4","etats_decor":[],"enigmes":[{"id":"e4-1","escale":4,"ordre":1,"titre":"Les cases effacées","decor":"bureau","objet_principal":"objet-1","objets_cliquables":["objet-1","objet-2","objet-3","objet-4"],"personnage_emetteur":"lina","probleme_narratif":"Lina complète le tableau des relevés.","enjeu":"Sans les cases, les relevés sont incomplets.","episode_du_roman":"Relevés de la station fictive de l'école (données du jeu) ; Programme de sciences et technologie du cycle 3 : réaliser et exploiter des mesu","competence_programme":"Lire et compléter un tableau à double entrée","pourquoi_ce_savoir_ici":"La salle « Le tableau des relevés — organiser et exploiter » repose sur cette notion.","reaction_du_decor":{"effet":"lumiere","description":"Le tableau se remplit case par case."},"liberte_ou_anachronisme":"Aucune liberté particulière signalée (jeu migré).","lecon":"releves","type":"plan","niveau_variantes":"Observateur (plan) ; Releveur (plan) ; Météorologue (plan) ; Prévisionniste (plan) ; Climatologue (qcm). Mousse : indices renvoyant à la fiche, énoncés courts ; lieutenant et second : justification par une phrase de la fiche.","correction_origine":"Dans un tableau à double entrée, chaque case croise une ligne (la grandeur mesurée) et une colonne (le jour). L'unité dépend de la ligne : °C pour la température, km/h pour le vent, mm pour la pluie. L'écart de mercredi vaut 21 − 12 = 9 °C.","matelot":{"titre":"Cases à retrouver","colonnes":2,"cases":[{"libelle":"Case A : minimum de mardi","reponse":"11 °C"},{"libelle":"Case B : maximum de mercredi","reponse":"21 °C"},{"libelle":"Case C : vent de mercredi","reponse":"24 km/h"},{"libelle":"Case D : pluie de jeudi","reponse":"12 mm"}],"etiquettes":["11 °C","21 °C","24 km/h","12 mm","12 °C","21 mm"],"consigne":"La pluie a effacé quatre cases du tableau de Lina (A, B, C, D). Retrouve-les grâce à son carnet, puis place les bonnes étiquettes. Attention aux <b>unités</b>.<table class=\"tableau-releves\"><tr><th></th><th>Lun</th><th>Mar</th><th>Mer</th><th>Jeu</th><th>Ven</th></tr><tr><th>Minimum (°C)</th><td>9</td><td><b>A</b></td><td>12</td><td>8</td><td>7</td></tr><tr><th>Maximum (°C)</th><td>17</td><td>19</td><td><b>B</b></td><td>14</td><td>16</td></tr><tr><th>Vent (km/h)</th><td>12</td><td>18</td><td><b>C</b></td><td>30</td><td>8</td></tr><tr><th>Pluie (mm)</th><td>0</td><td>3</td><td>7</td><td><b>D</b></td><td>0</td></tr></table><p><i>Carnet de Lina :</i> « Mardi, au lever du jour, le thermomètre marquait 11 °C. Mercredi, au plus chaud, 21 °C. Mercredi, l'anémomètre indiquait 24 km/h. Jeudi, le pluviomètre était monté à 12 mm. »</p>","indices":["Lis le nom de la ligne pour trouver l'unité : une température ne peut pas être en mm.","A est le minimum de mardi, B le maximum de mercredi.","C est une vitesse de vent, D une hauteur de pluie."],"dialogue":"Coucou ! C'est moi qui tiens le cahier de la station. Mesurer chaque jour, c'est bien, mais si les nombres sont mélangés, on ne peut rien en tirer. Un tableau bien rangé, ça permet de comparer : quel jour était le plus froid ? le plus arrosé ? Tu m'aides à tout remettre en ordre ?"},"timonier":{"titre":"Cases à retrouver","colonnes":3,"cases":[{"libelle":"Case A : minimum de mardi","reponse":"11 °C"},{"libelle":"Case B : maximum de mercredi","reponse":"21 °C"},{"libelle":"Case C : vent de mercredi","reponse":"24 km/h"},{"libelle":"Case D : pluie de jeudi","reponse":"12 mm"},{"libelle":"Case E : écart de mercredi","reponse":"9 °C"}],"etiquettes":["11 °C","21 °C","24 km/h","12 mm","9 °C","33 °C","12 °C","24 mm"],"consigne":"La pluie a effacé cinq cases du tableau (A à E). Retrouve-les grâce au carnet de Lina, calcule celle qui manque, puis place les étiquettes. Attention aux <b>unités</b>.<table class=\"tableau-releves\"><tr><th></th><th>Lun</th><th>Mar</th><th>Mer</th><th>Jeu</th><th>Ven</th></tr><tr><th>Minimum (°C)</th><td>9</td><td><b>A</b></td><td>12</td><td>8</td><td>7</td></tr><tr><th>Maximum (°C)</th><td>17</td><td>19</td><td><b>B</b></td><td>14</td><td>16</td></tr><tr><th>Écart (°C)</th><td>8</td><td>8</td><td><b>E</b></td><td>6</td><td>9</td></tr><tr><th>Vent (km/h)</th><td>12</td><td>18</td><td><b>C</b></td><td>30</td><td>8</td></tr><tr><th>Pluie (mm)</th><td>0</td><td>3</td><td>7</td><td><b>D</b></td><td>0</td></tr></table><p><i>Carnet de Lina :</i> « Mardi, au lever du jour : 11 °C. Mercredi, au plus chaud : 21 °C. Mercredi, vent moyen : 24 km/h. Jeudi, pluviomètre : 12 mm. » La ligne « Écart » donne la différence entre le maximum et le minimum du jour.</p>","indices":["L'unité dépend de la ligne : °C, km/h ou mm.","E = maximum de mercredi − minimum de mercredi.","21 − 12 = 9."],"dialogue":"Coucou ! C'est moi qui tiens le cahier de la station. Mesurer chaque jour, c'est bien, mais si les nombres sont mélangés, on ne peut rien en tirer. Un tableau bien rangé, ça permet de comparer : quel jour était le plus froid ? le plus arrosé ? Tu m'aides à tout remettre en ordre ?"},"mousse":{"type":"plan","titre":"Cases à retrouver","colonnes":2,"cases":[{"libelle":"Case A : maximum de lundi","reponse":"17 °C"},{"libelle":"Case B : vent de mardi","reponse":"18 km/h"},{"libelle":"Case C : pluie de mercredi","reponse":"7 mm"}],"etiquettes":["17 °C","18 km/h","7 mm","17 mm"],"consigne":"La pluie a effacé trois cases du tableau de Lina (A, B, C). Retrouve-les grâce à son carnet, puis place les étiquettes. Une étiquette est en trop. Attention aux <b>unités</b>.<table class=\"tableau-releves\"><tr><th></th><th>Lun</th><th>Mar</th><th>Mer</th></tr><tr><th>Maximum (°C)</th><td><b>A</b></td><td>19</td><td>21</td></tr><tr><th>Vent (km/h)</th><td>12</td><td><b>B</b></td><td>24</td></tr><tr><th>Pluie (mm)</th><td>0</td><td>3</td><td><b>C</b></td></tr></table><p><i>Carnet de Lina :</i> « Lundi, au plus chaud : 17 °C. Mardi, le vent soufflait à 18 km/h. Mercredi, le pluviomètre indiquait 7 mm. »</p>","indices":["Ouvre la fiche « Organiser et exploiter des relevés » dans la Bibliothèque.","Lis le nom de la ligne pour trouver l'unité.","Une température ne s'écrit pas en mm."],"dialogue":"Coucou ! C'est moi qui tiens le cahier de la station. Mesurer chaque jour, c'est bien, mais si les nombres sont mélangés, on ne peut rien en tirer. Un tableau bien rangé, ça permet de comparer : quel jour était le plus froid ? le plus arrosé ? Tu m'aides à tout remettre en ordre ?"},"lieutenant":{"type":"plan","titre":"Cases à retrouver","colonnes":2,"cases":[{"libelle":"Case A : minimum de jeudi","reponse":"8 °C"},{"libelle":"Case B : maximum de vendredi","reponse":"16 °C"},{"libelle":"Case C : vent de lundi","reponse":"12 km/h"},{"libelle":"Case D : écart de jeudi","reponse":"6 °C"}],"etiquettes":["8 °C","16 °C","12 km/h","6 °C","12 mm","9 °C"],"consigne":"La pluie a effacé quatre cases du tableau (A à D). Retrouve-les grâce au carnet de Lina, calcule celle qui manque, puis place les étiquettes. Deux étiquettes sont en trop. Puis choisis la phrase de la fiche qui définit l'écart.<table class=\"tableau-releves\"><tr><th></th><th>Lun</th><th>Mar</th><th>Mer</th><th>Jeu</th><th>Ven</th></tr><tr><th>Minimum (°C)</th><td>9</td><td>11</td><td>12</td><td><b>A</b></td><td>7</td></tr><tr><th>Maximum (°C)</th><td>17</td><td>19</td><td>21</td><td>14</td><td><b>B</b></td></tr><tr><th>Écart (°C)</th><td>8</td><td>8</td><td>9</td><td><b>D</b></td><td>9</td></tr><tr><th>Vent (km/h)</th><td><b>C</b></td><td>18</td><td>24</td><td>30</td><td>8</td></tr></table><p><i>Carnet de Lina :</i> « Jeudi, au lever du jour : 8 °C. Vendredi, au plus chaud : 16 °C. Lundi, vent moyen : 12 km/h. » La ligne « Écart » donne la différence entre le maximum et le minimum du jour.</p>","indices":["L'unité dépend de la ligne.","Écart de jeudi : 14 − 8.","Les deux étiquettes en trop n'ont pas la bonne unité ou la bonne valeur."],"justification":{"question":"Quelle phrase de la fiche définit l'écart ?","options":["Un tableau à double entrée croise les grandeurs mesurées (lignes) et les dates (colonnes).","On cherche le minimum et le maximum, on calcule l'écart (maximum − minimum) et le cumul (somme, pour la pluie).","Une valeur sans unité ne veut rien dire : 12 peut être 12 °C, 12 km/h ou 12 mm.","Un diagramme en barres convient aux quantités (pluie de chaque jour). Une courbe montre l'évolution d'une grandeur qui varie en continu, comme la température."],"bonne":1},"dialogue":"Coucou ! C'est moi qui tiens le cahier de la station. Mesurer chaque jour, c'est bien, mais si les nombres sont mélangés, on ne peut rien en tirer. Un tableau bien rangé, ça permet de comparer : quel jour était le plus froid ? le plus arrosé ? Tu m'aides à tout remettre en ordre ?"},"second":{"type":"qcm","questions":[{"q":"Quel est l'écart de température le plus grand de la semaine ?","options":["9 °C (mardi)","8 °C (lundi)","10 °C (vendredi)","7 °C"],"bonne":0,"explication":"15 − 6 = 9."},{"q":"Quel est le cumul de la pluie ?","options":["15 mm","9 mm","4 mm","13 mm"],"bonne":0,"explication":"0 + 2 + 9 + 4 + 0 = 15."},{"q":"Pourquoi faut-il toujours écrire l'unité dans le tableau ?","options":["12 peut être 12 °C, 12 km/h ou 12 mm","Pour décorer le tableau","Parce que les nombres sont petits","Parce que le vent a une unité seulement"],"bonne":0,"explication":"Une valeur sans unité ne veut rien dire."}],"consigne":"Lina a rempli un tableau. Lis-le, réponds aux trois questions, puis choisis la phrase de la fiche qui justifie la question 3.<table class=\"tableau-releves\"><tr><th></th><th>Lun</th><th>Mar</th><th>Mer</th><th>Jeu</th><th>Ven</th></tr><tr><th>Minimum (°C)</th><td>4</td><td>6</td><td>3</td><td>5</td><td>2</td></tr><tr><th>Maximum (°C)</th><td>12</td><td>15</td><td>11</td><td>14</td><td>10</td></tr><tr><th>Vent (km/h)</th><td>15</td><td>22</td><td>35</td><td>20</td><td>10</td></tr><tr><th>Pluie (mm)</th><td>0</td><td>2</td><td>9</td><td>4</td><td>0</td></tr></table>","indices":["Écart : maximum − minimum, jour par jour.","Additionne la ligne « Pluie ».","Une valeur sans unité ne veut rien dire."],"justification":{"question":"Quelle phrase de la fiche justifie ta réponse à la question 3 ?","options":["Un tableau à double entrée croise les grandeurs mesurées (lignes) et les dates (colonnes).","On cherche le minimum et le maximum, on calcule l'écart (maximum − minimum) et le cumul (somme, pour la pluie).","Une valeur sans unité ne veut rien dire : 12 peut être 12 °C, 12 km/h ou 12 mm.","C'est une valeur impossible ou très éloignée des autres : un minimum plus élevé que le maximum du même jour, un chiffre recopié de travers."],"bonne":2},"dialogue":"Coucou ! C'est moi qui tiens le cahier de la station. Mesurer chaque jour, c'est bien, mais si les nombres sont mélangés, on ne peut rien en tirer. Un tableau bien rangé, ça permet de comparer : quel jour était le plus froid ? le plus arrosé ? Tu m'aides à tout remettre en ordre ?"}},{"id":"e4-2","escale":4,"ordre":2,"titre":"La valeur impossible","decor":"bureau","objet_principal":"objet-2","objets_cliquables":["objet-1","objet-2","objet-3","objet-4"],"personnage_emetteur":"lina","probleme_narratif":"Keita repère la valeur impossible.","enjeu":"Une valeur impossible fausse le bilan.","episode_du_roman":"Relevés de la station fictive de l'école (données du jeu) ; Météo-France, « Qu'est-ce que la température ? »","competence_programme":"Lire et compléter un tableau à double entrée","pourquoi_ce_savoir_ici":"La salle « Le tableau des relevés — organiser et exploiter » repose sur cette notion.","reaction_du_decor":{"effet":"eclat","description":"La valeur fautive s'efface."},"liberte_ou_anachronisme":"Aucune liberté particulière signalée (jeu migré).","lecon":"releves","type":"intrus","niveau_variantes":"Observateur (intrus) ; Releveur (intrus) ; Météorologue (intrus) ; Prévisionniste (intrus) ; Climatologue (vraifaux). Mousse : indices renvoyant à la fiche, énoncés courts ; lieutenant et second : justification par une phrase de la fiche.","correction_origine":"Une valeur aberrante est une mesure qui ne peut pas être juste : trop éloignée des autres, ou impossible (un minimum ne peut pas être plus élevé que le maximum du même jour). On ne la garde pas : on cherche d'où vient l'erreur.","matelot":{"cartes":[{"txt":"Lundi : 17 °C","sous":"maximum"},{"txt":"Mardi : 19 °C","sous":"maximum"},{"txt":"Mercredi : 21 °C","sous":"maximum"},{"txt":"Jeudi : 41 °C","sous":"maximum","intrus":true},{"txt":"Vendredi : 16 °C","sous":"maximum"}],"consigne":"Un relevé a été mal noté : le thermomètre avait été posé en plein soleil. Clique sur la valeur qui ne va pas avec les autres.","indices":["Compare les nombres : toute la semaine, le maximum reste entre 14 et 21 °C.","Un thermomètre au soleil chauffe beaucoup plus que l'air.","La valeur fausse dépasse de loin toutes les autres."],"dialogue":"Une valeur est impossible dans ce tableau. Laquelle ?"},"timonier":{"cartes":[{"txt":"Lundi","sous":"minimum 9 °C · maximum 17 °C"},{"txt":"Mardi","sous":"minimum 11 °C · maximum 19 °C"},{"txt":"Mercredi","sous":"minimum 12 °C · maximum 21 °C"},{"txt":"Jeudi","sous":"minimum 14 °C · maximum 8 °C","intrus":true},{"txt":"Vendredi","sous":"minimum 7 °C · maximum 16 °C"}],"consigne":"Un relevé contient une erreur de recopie : il est <b>impossible</b>. Clique dessus.","indices":["Le minimum est la valeur la plus basse de la journée ; le maximum, la plus haute.","Pour chaque jour, vérifie que le minimum est plus petit que le maximum.","Un jour a des valeurs inversées."],"dialogue":"Une valeur est impossible dans ce tableau. Laquelle ?"},"mousse":{"type":"intrus","cartes":[{"txt":"Lundi : 15 °C","intrus":false},{"txt":"Mardi : 17 °C","intrus":false},{"txt":"Mercredi : 16 °C","intrus":false},{"txt":"Jeudi : 38 °C","intrus":true}],"consigne":"Un relevé a été mal noté : le thermomètre avait été posé en plein soleil. Clique sur la valeur qui ne va pas avec les autres, puis vérifie.","indices":["Ouvre la fiche « Organiser et exploiter des relevés ».","Compare les nombres.","Un thermomètre au soleil chauffe beaucoup plus que l'air."],"dialogue":"Un de ces éléments n'est pas comme les autres. Trouvez-le."},"lieutenant":{"type":"intrus","cartes":[{"txt":"Lundi : minimum 8 °C, maximum 15 °C","intrus":false},{"txt":"Mardi : minimum 10 °C, maximum 17 °C","intrus":false},{"txt":"Mercredi : minimum 18 °C, maximum 11 °C","intrus":true},{"txt":"Jeudi : minimum 7 °C, maximum 13 °C","intrus":false},{"txt":"Vendredi : minimum 6 °C, maximum 12 °C","intrus":false}],"consigne":"Un relevé de la semaine contient une erreur : il est impossible. Clique dessus, puis choisis la phrase de la fiche qui définit une valeur aberrante.","indices":["Pour chaque jour, le minimum est plus petit que le maximum.","Un jour a des valeurs inversées.","Pour la justification : cherche la phrase qui parle d'un minimum plus élevé que le maximum."],"justification":{"question":"Quelle phrase de la fiche définit une valeur aberrante ?","options":["On cherche le minimum et le maximum, on calcule l'écart (maximum − minimum) et le cumul (somme, pour la pluie).","C'est une valeur impossible ou très éloignée des autres : un minimum plus élevé que le maximum du même jour, un chiffre recopié de travers.","On la repère, on cherche la cause et on ne l'utilise pas dans les calculs.","Une valeur sans unité ne veut rien dire : 12 peut être 12 °C, 12 km/h ou 12 mm."],"bonne":1},"dialogue":"Un de ces éléments n'est pas comme les autres. Trouvez-le."},"second":{"type":"vraifaux","affirmations":[{"txt":"Un minimum plus élevé que le maximum du même jour est une valeur aberrante.","vrai":true,"explication":"C'est impossible."},{"txt":"On utilise une valeur aberrante dans les calculs.","vrai":false,"explication":"On ne l'utilise pas."},{"txt":"On cherche la cause d'une valeur aberrante.","vrai":true,"explication":"On la repère d'abord."},{"txt":"Un diagramme en barres convient à la pluie de chaque jour.","vrai":true,"explication":"Pour les quantités."},{"txt":"Une courbe convient à la température.","vrai":true,"explication":"Elle varie en continu."},{"txt":"Un chiffre recopié de travers peut donner une valeur aberrante.","vrai":true,"explication":"C'est une erreur de recopie."}],"consigne":"Lina a noté six phrases sur les valeurs aberrantes et les graphiques. Pour chacune, réponds « Vrai » ou « Faux », puis choisis la phrase de la fiche qui dit ce qu'on fait d'une valeur aberrante.","indices":["Une valeur aberrante est impossible.","On ne la prend pas dans les calculs.","Barres : quantités. Courbe : évolution."],"justification":{"question":"Quelle phrase de la fiche dit ce qu'on fait d'une valeur aberrante ?","options":["C'est une valeur impossible ou très éloignée des autres : un minimum plus élevé que le maximum du même jour, un chiffre recopié de travers.","On la repère, on cherche la cause et on ne l'utilise pas dans les calculs.","Un diagramme en barres convient aux quantités (pluie de chaque jour). Une courbe montre l'évolution d'une grandeur qui varie en continu, comme la température.","On cherche le minimum et le maximum, on calcule l'écart (maximum − minimum) et le cumul (somme, pour la pluie)."],"bonne":1},"dialogue":"Voici mes affirmations. À vous de dire lesquelles sont vraies."}},{"id":"e4-3","escale":4,"ordre":3,"titre":"Ce que dit le tableau","decor":"bureau","objet_principal":"objet-3","objets_cliquables":["objet-1","objet-2","objet-3","objet-4"],"personnage_emetteur":"lina","probleme_narratif":"Madame Vasseur demande ce que dit le tableau.","enjeu":"Sans analyse, le tableau ne sert à rien.","episode_du_roman":"Relevés de la station fictive de l'école (données du jeu) ; Programme de sciences et technologie du cycle 3 : réaliser et exploiter des mesu","competence_programme":"Lire et compléter un tableau à double entrée","pourquoi_ce_savoir_ici":"La salle « Le tableau des relevés — organiser et exploiter » repose sur cette notion.","reaction_du_decor":{"effet":"calme","description":"Les chiffres se mettent à parler."},"liberte_ou_anachronisme":"Aucune liberté particulière signalée (jeu migré).","lecon":"releves","type":"trous","niveau_variantes":"Observateur (trous) ; Releveur (trous) ; Météorologue (trous) ; Prévisionniste (trous) ; Climatologue (tri). Mousse : indices renvoyant à la fiche, énoncés courts ; lieutenant et second : justification par une phrase de la fiche.","correction_origine":"Le minimum de la semaine est la plus petite valeur (7 °C, vendredi), le maximum la plus grande (21 °C, mercredi) ; l'écart est la différence : 21 − 7 = 14 °C. Le cumul de pluie est la somme : 22 mm.","matelot":{"texte":"La température la plus basse de la semaine est [[7 °C]], vendredi. La plus haute est [[21 °C]], mercredi. L'écart entre les deux est de [[14 °C]]. Le jour le plus arrosé est [[jeudi]].","etiquettes":["7 °C","21 °C","14 °C","jeudi","9 °C","lundi","28 °C"],"consigne":"Complète le résumé de la semaine à l'aide du tableau (minimum : 9, 11, 12, 8, 7 ; maximum : 17, 19, 21, 14, 16 ; pluie : 0, 3, 7, 12, 0).","indices":["Cherche le plus petit nombre de la ligne « minimum ».","Cherche le plus grand nombre de la ligne « maximum ».","Écart : 21 − 7."],"dialogue":"Que dit ce tableau ? Complétez avec les bons mots."},"timonier":{"texte":"La température la plus basse de la semaine est [[7 °C]] et la plus haute [[21 °C]] : l'écart est de [[14 °C]]. Il est tombé au total [[22 mm]] de pluie, et il n'a pas plu pendant [[2]] jours. Le vent le plus fort a soufflé [[jeudi]].","etiquettes":["7 °C","21 °C","14 °C","22 mm","2","jeudi","28 °C","12 mm","3","mercredi"],"consigne":"Complète le résumé de la semaine à l'aide du tableau (minimum : 9, 11, 12, 8, 7 °C ; maximum : 17, 19, 21, 14, 16 °C ; vent : 12, 18, 24, 30, 8 km/h ; pluie : 0, 3, 7, 12, 0 mm). Certaines étiquettes sont des pièges.","indices":["Écart : plus grande valeur moins plus petite valeur.","Cumul : 0 + 3 + 7 + 12 + 0.","Deux jours n'ont reçu aucune pluie ; le vent le plus fort a soufflé jeudi."],"dialogue":"Que dit ce tableau ? Complétez avec les bons mots."},"mousse":{"type":"trous","texte":"<p>La température la plus basse est [[9 °C]]. La plus haute est [[21 °C]]. L'écart entre les deux est de [[12 °C]].</p>","etiquettes":["9 °C","21 °C","12 °C","30 °C"],"consigne":"Complète le résumé de la semaine à l'aide du tableau (minimum : 9, 11, 12 ; maximum : 17, 19, 21). Clique sur une étiquette, puis sur le trou où elle va. Une étiquette est en trop.","indices":["Ouvre la fiche « Organiser et exploiter des relevés ».","Écart : plus grande valeur moins plus petite valeur.","21 − 9."],"dialogue":"Il manque des mots dans mon carnet. Remettez-les à leur place."},"lieutenant":{"type":"trous","texte":"<p>Le minimum le plus bas est [[7 °C]], le maximum le plus haut [[21 °C]] : l'écart total est de [[14 °C]]. Le [[cumul]] de pluie se calcule en additionnant les jours.</p>","etiquettes":["7 °C","21 °C","14 °C","cumul","écart","9 °C","28 °C"],"consigne":"Complète le résumé de la semaine à l'aide du tableau de la case précédente. Clique sur une étiquette, puis sur le trou où elle va. Trois étiquettes sont en trop. Puis choisis la phrase de la fiche qui définit le cumul.","indices":["Plus petit minimum, plus grand maximum.","21 − 7.","Le cumul est une somme."],"justification":{"question":"Quelle phrase de la fiche définit le cumul ?","options":["Un tableau à double entrée croise les grandeurs mesurées (lignes) et les dates (colonnes).","Un diagramme en barres convient aux quantités (pluie de chaque jour). Une courbe montre l'évolution d'une grandeur qui varie en continu, comme la température.","On cherche le minimum et le maximum, on calcule l'écart (maximum − minimum) et le cumul (somme, pour la pluie).","On la repère, on cherche la cause et on ne l'utilise pas dans les calculs."],"bonne":2},"dialogue":"Il manque des mots dans mon carnet. Remettez-les à leur place."},"second":{"type":"tri","colonnes":[{"id":"exact","titre":"Exact d'après le tableau"},{"id":"faux","titre":"Faux d'après le tableau"}],"cartes":[{"txt":"Le minimum le plus bas est 2 °C.","col":"exact"},{"txt":"Le cumul de pluie est de 15 mm.","col":"exact"},{"txt":"Le vent le plus fort a soufflé mercredi.","col":"exact"},{"txt":"Le maximum le plus haut est 14 °C.","col":"faux"},{"txt":"L'écart de lundi est de 7 °C.","col":"faux"},{"txt":"Il a plu tous les jours.","col":"faux"}],"consigne":"Lina a rempli un tableau (minimum : 4, 6, 3, 5, 2 ; maximum : 12, 15, 11, 14, 10 ; vent : 15, 22, 35, 20, 10 ; pluie : 0, 2, 9, 4, 0). Range chaque résumé : exact ou faux d'après le tableau ? Puis choisis la phrase de la fiche qui décrit le tableau à double entrée.","indices":["Le plus petit des minimums, le plus grand des maximums.","Additionne la ligne « Pluie ».","Écart de lundi : 12 − 4."],"justification":{"question":"Quelle phrase de la fiche décrit le tableau à double entrée ?","options":["Un tableau à double entrée croise les grandeurs mesurées (lignes) et les dates (colonnes).","On cherche le minimum et le maximum, on calcule l'écart (maximum − minimum) et le cumul (somme, pour la pluie).","Une valeur sans unité ne veut rien dire : 12 peut être 12 °C, 12 km/h ou 12 mm.","Un diagramme en barres convient aux quantités (pluie de chaque jour). Une courbe montre l'évolution d'une grandeur qui varie en continu, comme la température."],"bonne":0},"dialogue":"Il faut tout ranger. Placez chaque carte dans la bonne colonne."}},{"id":"e4-4","escale":4,"ordre":4,"titre":"Le graphique de la pluie","decor":"bureau","objet_principal":"objet-4","objets_cliquables":["objet-1","objet-2","objet-3","objet-4"],"personnage_emetteur":"lina","probleme_narratif":"Tiago lit le graphique de la pluie.","enjeu":"Mal lu, le graphique trompe.","episode_du_roman":"Relevés de la station fictive de l'école (données du jeu) ; Programme de sciences et technologie du cycle 3 : réaliser et exploiter des mesu","competence_programme":"Lire et compléter un tableau à double entrée","pourquoi_ce_savoir_ici":"La salle « Le tableau des relevés — organiser et exploiter » repose sur cette notion.","reaction_du_decor":{"effet":"carte","description":"Les barres du graphique montent."},"liberte_ou_anachronisme":"Aucune liberté particulière signalée (jeu migré).","lecon":"releves","type":"qcm","niveau_variantes":"Météorologue (qcm) ; Prévisionniste (qcm) ; Climatologue (trous). Mousse : indices renvoyant à la fiche, énoncés courts ; lieutenant et second : justification par une phrase de la fiche.","correction_origine":"Dans un diagramme en barres, la hauteur de chaque barre se lit sur l'axe gradué. Jeudi (12 mm) a reçu 5 mm de plus que mercredi (7 mm). Lundi et vendredi n'ont pas de barre : il n'a pas plu.","niveaux":["timonier","lieutenant","second"],"timonier":{"questions":[{"q":"Quel jour a été le plus arrosé ?","options":["jeudi","mercredi","vendredi","mardi"],"bonne":0,"explication":"La barre de jeudi est la plus haute : 12 mm."},{"q":"Combien de millimètres de plus sont tombés jeudi que mercredi ?","options":["5 mm","7 mm","12 mm","19 mm"],"bonne":0,"explication":"12 − 7 = 5 mm."},{"q":"Combien de jours sans pluie compte cette semaine ?","options":["2","0","1","3"],"bonne":0,"explication":"Lundi et vendredi n'ont pas de barre."}],"consigne":"Lina a transformé la ligne « pluie » du tableau en diagramme en barres. Lis-le, puis réponds aux trois questions.<svg class=\"graphe-consigne\" viewBox=\"0 0 480 230\" role=\"img\" aria-label=\"Diagramme en barres : hauteur de pluie relevée chaque jour, du lundi au vendredi, graduée de 0 à 14 millimètres\"><line x1=\"56\" y1=\"196.0\" x2=\"460\" y2=\"196.0\" stroke=\"#d5dde5\"/><text x=\"48\" y=\"200.0\" font-size=\"11\" text-anchor=\"end\" font-family=\"Arial,sans-serif\" fill=\"#1f2430\">0</text><line x1=\"56\" y1=\"171.4\" x2=\"460\" y2=\"171.4\" stroke=\"#d5dde5\"/><text x=\"48\" y=\"175.4\" font-size=\"11\" text-anchor=\"end\" font-family=\"Arial,sans-serif\" fill=\"#1f2430\">2</text><line x1=\"56\" y1=\"146.9\" x2=\"460\" y2=\"146.9\" stroke=\"#d5dde5\"/><text x=\"48\" y=\"150.9\" font-size=\"11\" text-anchor=\"end\" font-family=\"Arial,sans-serif\" fill=\"#1f2430\">4</text><line x1=\"56\" y1=\"122.3\" x2=\"460\" y2=\"122.3\" stroke=\"#d5dde5\"/><text x=\"48\" y=\"126.3\" font-size=\"11\" text-anchor=\"end\" font-family=\"Arial,sans-serif\" fill=\"#1f2430\">6</text><line x1=\"56\" y1=\"97.7\" x2=\"460\" y2=\"97.7\" stroke=\"#d5dde5\"/><text x=\"48\" y=\"101.7\" font-size=\"11\" text-anchor=\"end\" font-family=\"Arial,sans-serif\" fill=\"#1f2430\">8</text><line x1=\"56\" y1=\"73.1\" x2=\"460\" y2=\"73.1\" stroke=\"#d5dde5\"/><text x=\"48\" y=\"77.1\" font-size=\"11\" text-anchor=\"end\" font-family=\"Arial,sans-serif\" fill=\"#1f2430\">10</text><line x1=\"56\" y1=\"48.6\" x2=\"460\" y2=\"48.6\" stroke=\"#d5dde5\"/><text x=\"48\" y=\"52.6\" font-size=\"11\" text-anchor=\"end\" font-family=\"Arial,sans-serif\" fill=\"#1f2430\">12</text><line x1=\"56\" y1=\"24.0\" x2=\"460\" y2=\"24.0\" stroke=\"#d5dde5\"/><text x=\"48\" y=\"28.0\" font-size=\"11\" text-anchor=\"end\" font-family=\"Arial,sans-serif\" fill=\"#1f2430\">14</text><text x=\"96\" y=\"212\" font-size=\"12\" text-anchor=\"middle\" font-family=\"Arial,sans-serif\" fill=\"#1f2430\">Lun</text><rect x=\"154\" y=\"159.1\" width=\"44\" height=\"36.9\" fill=\"#5aa0d8\" stroke=\"#1d5c8f\"/><text x=\"176\" y=\"212\" font-size=\"12\" text-anchor=\"middle\" font-family=\"Arial,sans-serif\" fill=\"#1f2430\">Mar</text><rect x=\"234\" y=\"110.0\" width=\"44\" height=\"86.0\" fill=\"#5aa0d8\" stroke=\"#1d5c8f\"/><text x=\"256\" y=\"212\" font-size=\"12\" text-anchor=\"middle\" font-family=\"Arial,sans-serif\" fill=\"#1f2430\">Mer</text><rect x=\"314\" y=\"48.6\" width=\"44\" height=\"147.4\" fill=\"#5aa0d8\" stroke=\"#1d5c8f\"/><text x=\"336\" y=\"212\" font-size=\"12\" text-anchor=\"middle\" font-family=\"Arial,sans-serif\" fill=\"#1f2430\">Jeu</text><text x=\"416\" y=\"212\" font-size=\"12\" text-anchor=\"middle\" font-family=\"Arial,sans-serif\" fill=\"#1f2430\">Ven</text><line x1=\"56\" y1=\"196\" x2=\"460\" y2=\"196\" stroke=\"#1f2430\" stroke-width=\"1.5\"/><line x1=\"56\" y1=\"196\" x2=\"56\" y2=\"18\" stroke=\"#1f2430\" stroke-width=\"1.5\"/><text x=\"12\" y=\"16\" font-size=\"11\" font-family=\"Arial,sans-serif\" fill=\"#1f2430\">Pluie (mm)</text></svg>","indices":["Suis le haut de chaque barre jusqu'à l'axe de gauche.","Une graduation de l'axe vaut 2 mm.","Jeudi : 12 mm ; mercredi : 7 mm."],"dialogue":"Lisez bien le graphique de la pluie."},"lieutenant":{"type":"qcm","questions":[{"q":"Quel jour a été le plus arrosé ?","options":["Mercredi","Jeudi","Mardi","Lundi"],"bonne":0,"explication":"9 mm."},{"q":"De combien de millimètres mercredi dépasse-t-il jeudi ?","options":["5 mm","9 mm","4 mm","13 mm"],"bonne":0,"explication":"9 − 4 = 5."},{"q":"Combien de jours sans pluie ?","options":["2","1","3","0"],"bonne":0,"explication":"Lundi et vendredi."}],"consigne":"Lina a tracé la ligne « pluie » en diagramme : lundi 0 mm, mardi 2 mm, mercredi 9 mm, jeudi 4 mm, vendredi 0 mm. Réponds aux trois questions, puis choisis la phrase de la fiche qui justifie le choix du diagramme en barres.","indices":["Suis le haut de chaque barre.","Soustrais 4 de 9.","Les barres de lundi et de vendredi sont vides."],"justification":{"question":"Quelle phrase de la fiche justifie le diagramme en barres ?","options":["Un tableau à double entrée croise les grandeurs mesurées (lignes) et les dates (colonnes).","On cherche le minimum et le maximum, on calcule l'écart (maximum − minimum) et le cumul (somme, pour la pluie).","Un diagramme en barres convient aux quantités (pluie de chaque jour). Une courbe montre l'évolution d'une grandeur qui varie en continu, comme la température.","C'est une valeur impossible ou très éloignée des autres : un minimum plus élevé que le maximum du même jour, un chiffre recopié de travers."],"bonne":2},"dialogue":"J'ai quelques questions pour vous. Lisez bien le document avant de répondre."},"second":{"type":"trous","texte":"<p>Un tableau à double entrée croise les [[grandeurs]] mesurées et les [[dates]]. Une valeur sans [[unité]] ne veut rien dire. On calcule l'[[écart]] et le [[cumul]].</p>","etiquettes":["grandeurs","dates","unité","écart","cumul","couleur","prix","vent","courbe"],"consigne":"Lina rédige la fiche de méthode, mais il manque des mots. Clique sur une étiquette, puis sur le trou où elle va. Quatre étiquettes sont en trop. Puis choisis la phrase de la fiche qui justifie le mot « unité ».","indices":["Les lignes : les grandeurs. Les colonnes : les dates.","12 peut être 12 °C, 12 km/h ou 12 mm.","Écart et cumul : deux calculs."],"justification":{"question":"Quelle phrase de la fiche justifie le mot « unité » ?","options":["Un tableau à double entrée croise les grandeurs mesurées (lignes) et les dates (colonnes).","Une valeur sans unité ne veut rien dire : 12 peut être 12 °C, 12 km/h ou 12 mm.","On cherche le minimum et le maximum, on calcule l'écart (maximum − minimum) et le cumul (somme, pour la pluie).","On la repère, on cherche la cause et on ne l'utilise pas dans les calculs."],"bonne":1},"dialogue":"Il manque des mots dans mon carnet. Remettez-les à leur place."}}]},{"numero":5,"id":"le-bulletin-du-jour-de-la-mesure-a-la-prevision","titre":"Le bulletin du jour","lieu":"📡 La salle de prévision","matiere":"","periode_conseillee":"","episode":"Un grand écran montre une carte, un soleil, un nuage et une flèche de vent. Le micro attend. Pour lancer le bulletin, il faut entrer la valeur de vérité de mercredi : trois mesures justes.","scenarimage":"","mot":"PRÉVOIR","mot_origine":"Le mot-clé de la salle 5.","air":null,"cinematique_ouverture":"transition-e5","cinematique_fin":"fin-e5","etats_decor":[],"enigmes":[{"id":"e5-1","escale":5,"ordre":1,"titre":"Météo ou climat ?","decor":"studio","objet_principal":"objet-1","objets_cliquables":["objet-1","objet-2","objet-3","objet-4"],"personnage_emetteur":"vasseur","probleme_narratif":"Madame Vasseur trie ce qui relève de la météo ou du climat.","enjeu":"Les confondre brouille la prévision.","episode_du_roman":"Météo-France, « Quelle différence entre météo et climat ? » : le climat se décrit sur des périodes de référence de 30 ans","competence_programme":"Relier des mesures à une prévision et à des conseils","pourquoi_ce_savoir_ici":"La salle « Le bulletin du jour — de la mesure à la prévision » repose sur cette notion.","reaction_du_decor":{"effet":"eclat","description":"Le ciel se dégage derrière le mur."},"liberte_ou_anachronisme":"Aucune liberté particulière signalée (jeu migré).","lecon":"bulletin","type":"tri","niveau_variantes":"Observateur (tri) ; Releveur (tri) ; Météorologue (tri) ; Prévisionniste (tri) ; Climatologue (tri). Mousse : indices renvoyant à la fiche, énoncés courts ; lieutenant et second : justification par une phrase de la fiche.","correction_origine":"La météo décrit le temps qu'il fait à un endroit et à un moment donnés : il change d'heure en heure. Le climat décrit le temps habituel d'une région, calculé comme une moyenne sur une longue période (trente ans pour les climatologues).","matelot":{"colonnes":[{"id":"meteo","titre":"Météo"},{"id":"climat","titre":"Climat"}],"cartes":[{"txt":"Demain, il pleuvra l'après-midi.","col":"meteo"},{"txt":"Ce matin, il fait 12 °C dans la cour.","col":"meteo"},{"txt":"Mercredi, le vent soufflait à 24 km/h.","col":"meteo"},{"txt":"Au Sahara, il pleut très peu tout au long de l'année.","col":"climat"},{"txt":"En général, il pleut plus à Brest qu'à Marseille.","col":"climat"},{"txt":"Chez nous, l'hiver est en général plus froid que l'été.","col":"climat"}],"consigne":"Madame Vasseur a mélangé ses fiches. Range chaque phrase : parle-t-elle de la <b>météo</b> (le temps d'un jour précis) ou du <b>climat</b> (le temps habituel, sur une très longue durée) ?","indices":["Une phrase avec « demain », « ce matin » ou « mercredi » parle de météo.","Une phrase avec « en général » ou « tout au long de l'année » parle de climat.","Il y a trois phrases de chaque sorte."],"dialogue":"Dernier module. Mesurer, c'est bien ; prévoir, c'est mieux. La météo, c'est le temps qu'il fait aujourd'hui et dans les jours qui viennent. Le climat, c'est autre chose : une moyenne sur trente ans. Montrez-moi que vous ne les confondez pas, puis entrez la valeur de vérité de mercredi : la température maximale, la vitesse du vent et la hauteur de pluie."},"timonier":{"colonnes":[{"id":"meteo","titre":"Météo"},{"id":"climat","titre":"Climat"}],"cartes":[{"txt":"Demain, il pleuvra l'après-midi.","col":"meteo"},{"txt":"Ce matin, il fait 12 °C dans la cour.","col":"meteo"},{"txt":"Cette nuit, un orage a déréglé la station.","col":"meteo"},{"txt":"Jeudi, le vent a soufflé à 30 km/h.","col":"meteo"},{"txt":"Au Sahara, il pleut très peu tout au long de l'année.","col":"climat"},{"txt":"En moyenne, il pleut plus à Brest qu'à Marseille.","col":"climat"},{"txt":"Les « normales » de température sont calculées sur trente ans.","col":"climat"},{"txt":"Chez nous, les hivers sont en général plus froids que les étés.","col":"climat"}],"consigne":"Range chaque phrase : <b>météo</b> (le temps d'un moment ou d'un jour précis) ou <b>climat</b> (une moyenne sur une longue période, en général trente ans) ?","indices":["Un seul jour ou un seul événement : météo.","Une moyenne ou une habitude sur des années : climat.","Il y a quatre phrases de chaque sorte."],"dialogue":"Dernier module. Mesurer, c'est bien ; prévoir, c'est mieux. La météo, c'est le temps qu'il fait aujourd'hui et dans les jours qui viennent. Le climat, c'est autre chose : une moyenne sur trente ans. Montrez-moi que vous ne les confondez pas, puis entrez la valeur de vérité de mercredi : la température maximale, la vitesse du vent et la hauteur de pluie."},"mousse":{"type":"tri","colonnes":[{"id":"meteo","titre":"Météo"},{"id":"climat","titre":"Climat"}],"cartes":[{"txt":"Demain, il pleuvra l'après-midi.","col":"meteo"},{"txt":"Ce matin, il fait 12 °C dans la cour.","col":"meteo"},{"txt":"Au Sahara, il pleut très peu tout au long de l'année.","col":"climat"},{"txt":"Chez nous, l'hiver est en général plus froid que l'été.","col":"climat"}],"consigne":"Madame Vasseur a mélangé ses fiches. Range chaque phrase : météo (un jour précis) ou climat (le temps habituel) ? Clique sur une carte, puis sur une colonne.","indices":["Ouvre la fiche « De la mesure à la prévision : météo et climat » dans la Bibliothèque.","« Demain » ou « ce matin » : météo.","« En général » : climat."],"dialogue":"Dernier module. Mesurer, c'est bien ; prévoir, c'est mieux. La météo, c'est le temps qu'il fait aujourd'hui et dans les jours qui viennent. Le climat, c'est autre chose : une moyenne sur trente ans. Montrez-moi que vous ne les confondez pas, puis entrez la valeur de vérité de mercredi : la température maximale, la vitesse du vent et la hauteur de pluie."},"lieutenant":{"type":"tri","colonnes":[{"id":"meteo","titre":"Météo"},{"id":"climat","titre":"Climat"}],"cartes":[{"txt":"Hier, il est tombé 12 mm de pluie.","col":"meteo"},{"txt":"Ce soir, le vent va tourner au nord.","col":"meteo"},{"txt":"Samedi, il gèle à −4 °C.","col":"meteo"},{"txt":"À Brest, il pleut plus qu'à Marseille en moyenne.","col":"climat"},{"txt":"Les normales sont calculées sur trente ans.","col":"climat"},{"txt":"Sous l'équateur, il fait chaud toute l'année.","col":"climat"}],"consigne":"Madame Vasseur classe des phrases. Range chaque phrase : météo ou climat ? Puis choisis la phrase de la fiche qui définit le climat.","indices":["Un jour précis : météo.","Une moyenne sur des années : climat.","Trente ans : les normales."],"justification":{"question":"Quelle phrase de la fiche définit le climat ?","options":["Météo : l'état de l'atmosphère à un endroit et à un moment donnés ; il change d'heure en heure.","Climat : une moyenne statistique de ces conditions sur une longue période.","Une prévision s'appuie sur des milliers de mesures fiables, prises partout de la même façon.","Une journée froide ne dit rien, à elle seule, du climat : il faut de longues séries de mesures."],"bonne":1},"dialogue":"Dernier module. Mesurer, c'est bien ; prévoir, c'est mieux. La météo, c'est le temps qu'il fait aujourd'hui et dans les jours qui viennent. Le climat, c'est autre chose : une moyenne sur trente ans. Montrez-moi que vous ne les confondez pas, puis entrez la valeur de vérité de mercredi : la température maximale, la vitesse du vent et la hauteur de pluie."},"second":{"type":"tri","colonnes":[{"id":"oui","titre":"La fiche l'affirme"},{"id":"non","titre":"La fiche ne l'affirme pas"}],"cartes":[{"txt":"Une prévision s'appuie sur des milliers de mesures fiables.","col":"oui"},{"txt":"Les normales sont calculées sur trente ans.","col":"oui"},{"txt":"Il faut de longues séries de mesures pour parler du climat.","col":"oui"},{"txt":"Une seule journée froide suffit à décrire le climat.","col":"non"},{"txt":"La météo est une moyenne sur trente ans.","col":"non"},{"txt":"Le climat change d'heure en heure.","col":"non"}],"consigne":"Madame Vasseur classe des affirmations. Range chaque affirmation : la fiche l'affirme, ou elle ne l'affirme pas. Puis choisis la phrase de la fiche qui explique pourquoi une journée froide ne dit rien du climat.","indices":["La météo change d'heure en heure.","Le climat est une moyenne sur une longue période.","Une seule journée ne suffit pas."],"justification":{"question":"Quelle phrase de la fiche explique pourquoi une journée froide ne dit rien du climat ?","options":["Climat : une moyenne statistique de ces conditions sur une longue période.","Une journée froide ne dit rien, à elle seule, du climat : il faut de longues séries de mesures.","Les climatologues utilisent des périodes de référence de trente ans ; les moyennes obtenues s'appellent les « normales ».","Météo : l'état de l'atmosphère à un endroit et à un moment donnés ; il change d'heure en heure."],"bonne":1},"dialogue":"Dernier module. Mesurer, c'est bien ; prévoir, c'est mieux. La météo, c'est le temps qu'il fait aujourd'hui et dans les jours qui viennent. Le climat, c'est autre chose : une moyenne sur trente ans. Montrez-moi que vous ne les confondez pas, puis entrez la valeur de vérité de mercredi : la température maximale, la vitesse du vent et la hauteur de pluie."}},{"id":"e5-2","escale":5,"ordre":2,"titre":"Prévoir la sortie","decor":"studio","objet_principal":"objet-2","objets_cliquables":["objet-1","objet-2","objet-3","objet-4"],"personnage_emetteur":"vasseur","probleme_narratif":"Tiago associe mesures et conseils.","enjeu":"Une mauvaise prévision met l'équipe en danger.","episode_du_roman":"Programme de sciences et technologie du cycle 3 : réaliser et exploiter des mesures météorologiques ; Relevés de la station fictive de l'éco","competence_programme":"Relier des mesures à une prévision et à des conseils","pourquoi_ce_savoir_ici":"La salle « Le bulletin du jour — de la mesure à la prévision » repose sur cette notion.","reaction_du_decor":{"effet":"calme","description":"Un pictogramme de soleil s'affiche sur la carte."},"liberte_ou_anachronisme":"Aucune liberté particulière signalée (jeu migré).","lecon":"bulletin","type":"association","niveau_variantes":"Observateur (association) ; Releveur (association) ; Météorologue (association) ; Prévisionniste (qcm) ; Climatologue (vraifaux). Mousse : indices renvoyant à la fiche, énoncés courts ; lieutenant et second : justification par une phrase de la fiche.","correction_origine":"Une prévision sert à décider : on s'équipe contre la pluie, le froid ou le soleil, et on renonce à une activité quand le vent ou l'orage la rendent dangereuse.","matelot":{"paires":[{"g":"Pluie annoncée l'après-midi","d":"Prendre un vêtement de pluie"},{"g":"Vent frais, force 6","d":"Reporter la sortie en bateau"},{"g":"Soleil et 21 °C","d":"Casquette et gourde d'eau"},{"g":"−2 °C au petit matin","d":"Bonnet, gants, attention au sol glissant"}],"consigne":"Pour la sortie, relie chaque prévision (à gauche) au bon conseil (à droite).","indices":["Contre la pluie, il faut un vêtement qui ne laisse pas passer l'eau.","Avec un vent fort, on ne sort pas en bateau.","Sous zéro, le sol peut devenir glissant."],"dialogue":"Prévoir la sortie : associez chaque mesure à son conseil."},"timonier":{"paires":[{"g":"Averses en fin de journée","d":"Prévoir un vêtement de pluie pour le retour"},{"g":"Vent frais, force 6","d":"Reporter la sortie en bateau"},{"g":"Soleil et 21 °C","d":"Casquette et gourde d'eau"},{"g":"−2 °C au petit matin","d":"Bonnet, gants, attention au sol glissant"},{"g":"Orage annoncé","d":"Rester à l'abri, loin des arbres isolés"}],"consigne":"Pour la sortie, relie chaque prévision (à gauche) au conseil qui en découle (à droite).","indices":["Chaque conseil répond à un seul danger ou à une seule gêne.","Pendant un orage, on reste à l'abri et on s'éloigne des arbres isolés.","Sous zéro, l'eau gèle : le sol peut glisser."],"dialogue":"Prévoir la sortie : associez chaque mesure à son conseil."},"mousse":{"type":"association","paires":[{"g":"Pluie annoncée l'après-midi","d":"prendre un vêtement de pluie"},{"g":"Soleil et 21 °C","d":"casquette et gourde d'eau"},{"g":"−2 °C au petit matin","d":"bonnet, gants, sol glissant"}],"consigne":"Pour la sortie, relie chaque prévision au bon conseil. Clique à gauche, puis à droite.","indices":["Ouvre la fiche « De la mesure à la prévision : météo et climat ».","Contre la pluie, un vêtement qui ne laisse pas passer l'eau.","Sous zéro, on se couvre."],"dialogue":"Il faut relier chaque élément à ce qui lui correspond."},"lieutenant":{"type":"qcm","questions":[{"q":"Quelle température maximale annonce le bulletin ?","options":["21 °C","24 °C","7 °C","12 °C"],"bonne":0,"explication":"Maximale : 21 °C."},{"q":"Quel conseil pour la fin de journée ?","options":["Prendre un vêtement de pluie","Prendre un chapeau de soleil","Prendre des gants","Rester à l'ombre"],"bonne":0,"explication":"Averses en fin de journée."},{"q":"Sur quoi s'appuie la prévision ?","options":["Sur des milliers de mesures fiables, prises partout de la même façon","Sur une seule mesure","Sur le hasard","Sur la couleur du ciel"],"bonne":0,"explication":"Une prévision repose sur des mesures."}],"consigne":"<div class='doc-carnet'><b>Bulletin de la station</b> (inventé pour le jeu). « Mercredi : température maximale 21 °C, vent moyen 24 km/h, pluie 7 mm. Pour la sortie, matinée sèche, puis averses en fin de journée. »</div> Réponds aux trois questions, puis choisis la phrase de la fiche qui justifie la question 3.","indices":["Relis la température maximale.","Averses : vêtement de pluie.","La prévision s'appuie sur des mesures."],"justification":{"question":"Quelle phrase de la fiche justifie ta réponse à la question 3 ?","options":["À l'école, nos trois capteurs donnent déjà l'essentiel : température, vent, pluie.","Une prévision s'appuie sur des milliers de mesures fiables, prises partout de la même façon.","Météo : l'état de l'atmosphère à un endroit et à un moment donnés ; il change d'heure en heure.","Les climatologues utilisent des périodes de référence de trente ans ; les moyennes obtenues s'appellent les « normales »."],"bonne":1},"dialogue":"J'ai quelques questions pour vous. Lisez bien le document avant de répondre."},"second":{"type":"vraifaux","affirmations":[{"txt":"Nos trois capteurs de l'école mesurent la température, le vent et la pluie.","vrai":true,"explication":"L'essentiel."},{"txt":"Le bulletin traduit les nombres en décisions.","vrai":true,"explication":"Par exemple, prendre un vêtement de pluie."},{"txt":"Une prévision s'appuie sur une seule mesure.","vrai":false,"explication":"Sur des milliers."},{"txt":"Les mesures sont prises partout de la même façon.","vrai":true,"explication":"Pour être fiables."},{"txt":"La météo est une moyenne sur trente ans.","vrai":false,"explication":"C'est le climat."},{"txt":"Les normales sont des moyennes sur dix ans.","vrai":false,"explication":"Sur trente ans."}],"consigne":"Madame Vasseur a noté six phrases sur le bulletin. Pour chacune, réponds « Vrai » ou « Faux », puis choisis la phrase de la fiche qui cite les trois capteurs de l'école.","indices":["Trois capteurs : température, vent, pluie.","Une prévision repose sur de nombreuses mesures.","Les normales : trente ans."],"justification":{"question":"Quelle phrase de la fiche cite les trois capteurs de l'école ?","options":["À l'école, nos trois capteurs donnent déjà l'essentiel : température, vent, pluie.","Une prévision s'appuie sur des milliers de mesures fiables, prises partout de la même façon.","Météo : l'état de l'atmosphère à un endroit et à un moment donnés ; il change d'heure en heure.","Les climatologues utilisent des périodes de référence de trente ans ; les moyennes obtenues s'appellent les « normales »."],"bonne":0},"dialogue":"Voici mes affirmations. À vous de dire lesquelles sont vraies."}},{"id":"e5-3","escale":5,"ordre":3,"titre":"Le mot caché du bulletin","decor":"studio","objet_principal":"objet-3","objets_cliquables":["objet-1","objet-2","objet-3","objet-4"],"personnage_emetteur":"vasseur","probleme_narratif":"Lina a caché un mot dans le bulletin.","enjeu":"Sans le mot, le bulletin est incomplet.","episode_du_roman":"Relevés de la station fictive de l'école (données du jeu)","competence_programme":"Relier des mesures à une prévision et à des conseils","pourquoi_ce_savoir_ici":"La salle « Le bulletin du jour — de la mesure à la prévision » repose sur cette notion.","reaction_du_decor":{"effet":"carte","description":"Le bulletin s'imprime en lettres lumineuses."},"liberte_ou_anachronisme":"Aucune liberté particulière signalée (jeu migré).","lecon":"bulletin","type":"lettres","niveau_variantes":"Météorologue (lettres) ; Prévisionniste (lettres) ; Climatologue (lettres). Mousse : indices renvoyant à la fiche, énoncés courts ; lieutenant et second : justification par une phrase de la fiche.","correction_origine":"Mercredi, la girouette indiquait un vent venant de l'ouest : le mot caché est OUEST. Un vent d'ouest vient de l'ouest et souffle vers l'est.","niveaux":["timonier","lieutenant","second"],"timonier":{"cible":["O","U","E","S","T"],"texte":"<p>« Bonjour à tous. Mercredi, le <b data-l='T'>t</b>hermomètre est monté à 21 °C sous abri. L'anémomètr<b data-l='E'>e</b> a relevé un vent moyen de 24 km/h, force 4. <b data-l='N'>N</b>otre pluviomètre a recueilli 7 mm. Nous prévoyons pour la sortie une matinée <b data-l='S'>s</b>èche, puis des averses en fin de jo<b data-l='U'>u</b>rnée. Pensez à e<b data-l='M'>m</b>porter un coupe-vent. Rendez-v<b data-l='O'>o</b>us demain matin pou<b data-l='R'>r</b> les relevés. »</p>","consigne":"Dans le bulletin, huit lettres sont en relief, dans le désordre, et trois sont des pièges. Range les bonnes dans les cases pour écrire la direction d'où venait le vent mercredi.","indices":["Le capitaine Keïta l'a dit en quittant le mât.","C'est un point cardinal de cinq lettres.","Le mot commence par O."],"dialogue":"Un mot est caché dans le bulletin. Retrouvez-le."},"lieutenant":{"type":"lettres","cible":["C","L","I","M","A","T"],"texte":"<p>Bonjour à tous. Ce <b data-l='M'>m</b>atin, le thermomètre indique 12 °C. Le vent est faible, la pluie <b data-l='L'>l</b>oin. Demain, une <b data-l='T'>t</b>rès belle journée. Pour le <b data-l='C'>c</b>limat, il faut des années de mesures : <b data-l='I'>i</b>l ne suffit pas d'un jour. Nous <b data-l='A'>a</b>ttendons des nuages ce soir. Et <b data-l='S'>s</b>oyez prudents ! <b data-l='P'>p</b>as de panique.</p>","consigne":"Trouve le mot qui correspond à cette définition : « Le temps habituel d'une région, calculé sur une longue période. » Ses lettres sont cachées en couleur dans le bulletin de Lina, dans le désordre. Clique-les dans l'ordre qui forme le mot (6 lettres). Deux lettres sont des pièges.","indices":["Le mot a six lettres.","Il commence par C.","Météo : un jour. … : une longue période."],"justification":{"question":"Quelle phrase de la fiche cite ce mot ?","options":["Météo : l'état de l'atmosphère à un endroit et à un moment donnés ; il change d'heure en heure.","Une prévision s'appuie sur des milliers de mesures fiables, prises partout de la même façon.","Climat : une moyenne statistique de ces conditions sur une longue période.","À l'école, nos trois capteurs donnent déjà l'essentiel : température, vent, pluie."],"bonne":2},"dialogue":"Un mot est caché dans mon texte. Retrouvez-le."},"second":{"type":"lettres","cible":["N","O","R","M","A","L","E","S"],"texte":"<p>Bonjour à tous. Mercredi, le vent a soufflé à 24 km/h. Pour comparer nos <b data-l='M'>m</b>esures aux moyennes de trente ans, les climatologues l<b data-l='E'>e</b>s ordonnent <b data-l='R'>r</b>égulièrement. <b data-l='S'>S</b>elon la station, <b data-l='O'>o</b>n note aussi la pluie. Le <b data-l='L'>l</b>ong travail est <b data-l='A'>a</b>ttentif ; l'<b data-l='N'>n</b>ormalité se calcule sur trente ans. <b data-l='P'>p</b>ar contre, la météo d'un jour ne dit rien. <b data-l='T'>t</b>out le monde est invité.</p>","consigne":"Trouve le mot qui correspond à cette définition : « Valeur moyenne calculée sur trente ans. » Ses lettres sont cachées en couleur dans le bulletin de Lina, dans le désordre. Clique-les dans l'ordre qui forme le mot (8 lettres). Deux lettres sont des pièges.","indices":["Le mot a huit lettres.","Il commence par N et finit par S.","On parle des « … » de température sur trente ans."],"justification":{"question":"Quelle phrase de la fiche cite ce mot ?","options":["Climat : une moyenne statistique de ces conditions sur une longue période.","Les climatologues utilisent des périodes de référence de trente ans ; les moyennes obtenues s'appellent les « normales ».","Météo : l'état de l'atmosphère à un endroit et à un moment donnés ; il change d'heure en heure.","Une journée froide ne dit rien, à elle seule, du climat : il faut de longues séries de mesures."],"bonne":1},"dialogue":"Un mot est caché dans mon texte. Retrouvez-le."}},{"id":"e5-4","escale":5,"ordre":4,"titre":"La valeur de vérité","decor":"studio","objet_principal":"objet-4","objets_cliquables":["objet-1","objet-2","objet-3","objet-4"],"personnage_emetteur":"vasseur","probleme_narratif":"Keita a verrouillé la salle de prévision.","enjeu":"Sans le code, la station reste fermée.","episode_du_roman":"Relevés de la station fictive de l'école (données du jeu)","competence_programme":"Relier des mesures à une prévision et à des conseils","pourquoi_ce_savoir_ici":"La salle « Le bulletin du jour — de la mesure à la prévision » repose sur cette notion.","reaction_du_decor":{"effet":"ouverture","description":"La salle de prévision s'illumine : le coffre est prêt."},"liberte_ou_anachronisme":"Aucune liberté particulière signalée (jeu migré).","lecon":"bulletin","type":"code","niveau_variantes":"Observateur (code) ; Releveur (code) ; Météorologue (code) ; Prévisionniste (code) ; Climatologue (code). Mousse : indices renvoyant à la fiche, énoncés courts ; lieutenant et second : justification par une phrase de la fiche.","correction_origine":"Mercredi : 21 °C au maximum sous abri (module 1), un vent moyen de 24 km/h venant de l'ouest (module 2), 7 mm de pluie (module 3). Trois mesures fiables, prises avec les bons instruments et au bon endroit : c'est la base de toute prévision.","matelot":{"champs":[{"libelle":"Température maximale (°C)","valeur":"21","longueur":3},{"libelle":"Vent moyen (km/h)","valeur":"24","longueur":3},{"libelle":"Hauteur de pluie (mm)","valeur":"7","longueur":3}],"consigne":"Pour lancer le bulletin, entre la <b>valeur de vérité</b> de mercredi : les trois mesures justes que tu as retrouvées dans les modules 1, 2 et 3.","indices":["La température maximale a été lue à 15 h, dans le module 1.","La vitesse du vent de mercredi est celle d'une jolie brise, force 4 (module 2).","La pluie de mercredi a été lue dans le pluviomètre (module 3) : un nombre plus petit que 10."],"dialogue":"Dernier cadenas : trouvez le code qui valide la prévision."},"timonier":{"champs":[{"libelle":"Température maximale (°C)","valeur":"21","longueur":3},{"libelle":"Vent moyen (km/h)","valeur":"24","longueur":3},{"libelle":"Hauteur de pluie (mm)","valeur":"7","longueur":3}],"consigne":"Pour lancer le bulletin, entre la <b>valeur de vérité</b> de mercredi : la température maximale sous abri, la vitesse moyenne du vent et la hauteur de pluie. Toutes les trois ont été lues dans les modules précédents.","indices":["Relis le tableau du module 4 : colonne « Mer ».","Température maximale : ligne « Maximum ». Vent : ligne « Vent ».","La pluie de mercredi a été lue dans le module 3 : un nombre plus petit que 10."],"dialogue":"Dernier cadenas : trouvez le code qui valide la prévision."},"mousse":{"type":"code","champs":[{"libelle":"Température maximale (°C)","valeur":"21","longueur":2},{"libelle":"Hauteur de pluie (mm)","valeur":"7","longueur":1}],"consigne":"Pour lancer le bulletin, entre la valeur de vérité de mercredi : la température maximale et la hauteur de pluie, lues dans les modules précédents.","indices":["Ouvre la fiche « De la mesure à la prévision : météo et climat ».","La température maximale a été lue à 15 h.","La pluie de mercredi : un nombre plus petit que 10."],"dialogue":"Ce cadenas ne s'ouvre qu'avec le bon code. Lisez bien le document."},"lieutenant":{"type":"code","champs":[{"libelle":"Température maximale (°C)","valeur":"14","longueur":2},{"libelle":"Vent moyen (km/h)","valeur":"30","longueur":2},{"libelle":"Hauteur de pluie (mm)","valeur":"12","longueur":2}],"consigne":"Pour lancer le bulletin, entre la valeur de vérité de jeudi, relue dans le tableau : le maximum, le vent moyen et la hauteur de pluie. Jeudi : minimum 8 °C, maximum 14 °C, vent 30 km/h, pluie 12 mm.","indices":["Relis la ligne « Maximum » du tableau.","Le vent de jeudi est le plus fort de la semaine.","La pluie de jeudi : 12 mm."],"justification":{"question":"Quelle phrase de la fiche cite les trois mesures du bulletin ?","options":["Une prévision s'appuie sur des milliers de mesures fiables, prises partout de la même façon.","À l'école, nos trois capteurs donnent déjà l'essentiel : température, vent, pluie.","Météo : l'état de l'atmosphère à un endroit et à un moment donnés ; il change d'heure en heure.","Une journée froide ne dit rien, à elle seule, du climat : il faut de longues séries de mesures."],"bonne":1},"dialogue":"Ce cadenas ne s'ouvre qu'avec le bon code. Lisez bien le document."},"second":{"type":"code","champs":[{"libelle":"Écart de température (°C)","valeur":"8","longueur":1},{"libelle":"Vent moyen (km/h)","valeur":"18","longueur":2},{"libelle":"Cumul de pluie lundi et mardi (mm)","valeur":"3","longueur":1}],"consigne":"Pour lancer le bulletin, entre la valeur de vérité de mardi, relue dans le tableau : l'écart de température (maximum 19 °C, minimum 11 °C), le vent moyen et le cumul de pluie de lundi et mardi (lundi 0 mm, mardi 3 mm). Mardi : vent 18 km/h.","indices":["Écart : 19 − 11.","Le vent de mardi est donné.","Cumul : 0 + 3."],"justification":{"question":"Quelle phrase de la fiche explique pourquoi les mesures doivent être fiables ?","options":["À l'école, nos trois capteurs donnent déjà l'essentiel : température, vent, pluie.","Météo : l'état de l'atmosphère à un endroit et à un moment donnés ; il change d'heure en heure.","Une prévision s'appuie sur des milliers de mesures fiables, prises partout de la même façon.","Climat : une moyenne statistique de ces conditions sur une longue période."],"bonne":2},"dialogue":"Ce cadenas ne s'ouvre qu'avec le bon code. Lisez bien le document."}}]}]},"lecons":{"rayons":[{"id":"lecons","titre":"Rayon des leçons","icone":"📖"}],"lecons":[{"id":"thermometre","rayon":"lecons","fiche":1,"icone":"📖","titre":"Mesurer la température de l'air","escale":1,"competence":"Lire un thermomètre, y compris sous zéro ; Savoir où et comment placer un thermomètre ; Distinguer température minimale et maximale","essentiel":"<h4>Un instrument : le thermomètre</h4><p>La <b>température</b> dit s'il fait chaud ou froid. On la mesure avec un <b>thermomètre</b>, en <b>degrés Celsius</b> (°C).</p><p>Pour lire un thermomètre, on regarde <b>où s'arrête le liquide</b>. On part du grand trait numéroté juste en dessous, puis on compte les petites graduations.</p><div class='encadre'><b>Une mesure juste</b><br>Le thermomètre se place <b>à l'ombre</b>, dans un <b>abri</b> blanc et aéré, à <b>1,50 m</b> du sol. Au soleil, il chaufferait lui-même et mentirait.</div><h4>Minimum et maximum</h4><p>Dans une journée, la température change. La plus basse s'appelle le <b>minimum</b> (souvent tôt le matin), la plus haute le <b>maximum</b> (souvent l'après-midi).</p><p>Sous zéro, on écrit un signe moins : <b>−3 °C</b> se lit « moins trois degrés ». À 0 °C, l'eau commence à geler.</p>","approfondi":"<h4>Le thermomètre et l'abri</h4><p>On mesure la <b>température de l'air</b> avec un thermomètre ou un capteur électronique, en <b>degrés Celsius</b> (°C). Météo-France la mesure <b>sous abri, à 1,50 m du sol</b>, dans un abri blanc et percé d'ouvertures : l'air y circule, mais le capteur est protégé du rayonnement du soleil et de la pluie.</p><div class='encadre'><b>Pourquoi des règles communes ?</b><br>Toutes les stations suivent les mêmes règles, fixées par l'Organisation météorologique mondiale. Ainsi, une mesure prise à Dijon peut être comparée à une mesure prise à Brest ou à Montréal.</div><h4>Lire une température</h4><p>On lit la graduation qui correspond au sommet du liquide, les yeux à sa hauteur. Sous le zéro, les températures sont <b>négatives</b> : plus le nombre après le signe moins est grand, plus il fait froid (−6 °C est plus froid que −1 °C).</p><h4>Minimum, maximum</h4><p>La <b>température minimale</b> est la plus basse de la journée, la <b>maximale</b> la plus haute. Le maximum n'a pas lieu à midi : il arrive souvent en milieu d'après-midi, quand le sol a chauffé toute la journée.</p><table class='tab-lecon'><tr><th>Mot</th><th>Définition</th></tr><tr><td><b>Température</b></td><td>Ce qui indique s'il fait chaud ou froid ; elle se mesure en degrés Celsius (°C).</td></tr><tr><td><b>Thermomètre</b></td><td>Instrument qui mesure la température.</td></tr><tr><td><b>Abri météorologique</b></td><td>Boîte blanche et aérée qui protège le thermomètre du soleil et de la pluie.</td></tr><tr><td><b>Minimum / maximum</b></td><td>La valeur la plus basse / la plus haute relevée pendant une période.</td></tr><tr><td><b>Température négative</b></td><td>Température inférieure à 0 °C, écrite avec le signe moins.</td></tr></table>","expert":"","dans_le_roman":"Voir la salle 1."},{"id":"vent","rayon":"lecons","fiche":2,"icone":"📖","titre":"Mesurer le vent : direction et vitesse","escale":2,"competence":"Utiliser les points cardinaux et la rose des vents ; Distinguer girouette et anémomètre ; Utiliser une échelle de Beaufort simplifiée","essentiel":"<h4>D'où vient le vent ?</h4><p>La <b>girouette</b> tourne avec le vent : elle indique la <b>direction d'où il vient</b>. Un vent d'ouest <b>vient de l'ouest</b>.</p><p>Pour nommer les directions, on utilise les <b>points cardinaux</b> : le <b>nord</b>, l'<b>est</b> (où le soleil se lève), le <b>sud</b> (où est le soleil à midi, en France) et l'<b>ouest</b> (où il se couche).</p><h4>À quelle vitesse ?</h4><p>L'<b>anémomètre</b> a des coupelles qui tournent d'autant plus vite que le vent est fort. Il mesure la <b>vitesse du vent</b>, en <b>kilomètres par heure</b> (km/h).</p><div class='encadre'><b>Sans instrument : l'échelle de Beaufort</b><br>Calme (moins de 1 km/h) : la fumée monte tout droit.<br>Légère brise (6 à 11 km/h) : on sent le vent sur le visage.<br>Jolie brise (20 à 28 km/h) : la poussière se soulève.<br>Vent frais (39 à 49 km/h) : les grosses branches s'agitent.</div>","approfondi":"<h4>Deux instruments, deux informations</h4><p>La <b>girouette</b> indique la <b>direction d'où vient</b> le vent : un vent de nord-ouest vient du nord-ouest. L'<b>anémomètre</b> mesure sa <b>vitesse</b>, en km/h ou en mètres par seconde (1 m/s = 3,6 km/h, car une heure compte 3 600 secondes).</p><h4>La rose des vents</h4><p>Elle porte les quatre points cardinaux (N, E, S, O) et les quatre directions intermédiaires (NE, SE, SO, NO). Chaque direction intermédiaire prend le nom de ses deux voisines, en commençant par nord ou sud.</p><div class='encadre'><b>Des mesures comparables</b><br>L'Organisation météorologique mondiale demande de mesurer le vent <b>à 10 m au-dessus d'un terrain dégagé</b>, loin des obstacles, et de retenir la <b>vitesse moyenne sur dix minutes</b>. Une pointe brève et plus forte s'appelle une <b>rafale</b>.</div><h4>L'échelle de Beaufort</h4><p>Elle classe le vent de la force 0 (calme, moins de 1 km/h) à la force 12 (ouragan, 118 km/h et plus), d'après sa vitesse et ses effets : force 2 (6 à 11 km/h), on sent le vent sur le visage ; force 4 (20 à 28 km/h), la poussière se soulève ; force 6 (39 à 49 km/h), les grosses branches s'agitent.</p><table class='tab-lecon'><tr><th>Mot</th><th>Définition</th></tr><tr><td><b>Girouette</b></td><td>Instrument qui indique la direction d'où vient le vent.</td></tr><tr><td><b>Anémomètre</b></td><td>Instrument qui mesure la vitesse du vent.</td></tr><tr><td><b>Points cardinaux</b></td><td>Nord, est, sud, ouest.</td></tr><tr><td><b>Échelle de Beaufort</b></td><td>Classement du vent de 0 (calme) à 12 (ouragan).</td></tr><tr><td><b>Rafale</b></td><td>Pointe de vent brève, plus forte que la vitesse moyenne.</td></tr></table>","expert":"","dans_le_roman":"Voir la salle 2."},{"id":"pluie","rayon":"lecons","fiche":3,"icone":"📖","titre":"Mesurer la pluie avec un pluviomètre","escale":3,"competence":"Lire la hauteur d'eau d'un pluviomètre ; Comprendre que 1 mm de pluie = 1 litre par mètre carré ; Calculer un cumul de pluie","essentiel":"<h4>Le pluviomètre</h4><p>Le <b>pluviomètre</b> recueille la pluie dans un tube gradué. On ne compte pas les gouttes : on lit une <b>hauteur d'eau</b>, en <b>millimètres</b> (mm).</p><div class='encadre'><b>1 mm de pluie = 1 litre d'eau sur chaque mètre carré.</b><br>Mercredi, avec 7 mm, il est tombé 7 litres sur chaque mètre carré de la cour.</div><h4>Bien l'utiliser</h4><p>On l'installe dans un <b>endroit dégagé</b>, loin des arbres et des murs. On le lit <b>chaque jour à la même heure</b>, on note la valeur, puis on le <b>vide</b>.</p><h4>Le cumul</h4><p>En additionnant la pluie de plusieurs jours, on obtient le <b>cumul</b> : 3 mm + 7 mm = 10 mm.</p>","approfondi":"<h4>Une hauteur, pas un volume</h4><p>Le pluviomètre mesure la <b>hauteur de précipitations</b>, en millimètres : c'est l'épaisseur de la couche d'eau qui couvrirait un sol plat si rien ne s'écoulait ni ne s'évaporait.</p><div class='encadre'><b>1 mm sur 1 m² = 1 litre</b>, car 1 mm × 1 m² = 1 dm³. Pour connaître le volume tombé sur une surface, on multiplie : 7 mm sur une cour de 200 m² font 7 × 200 = 1 400 litres.</div><h4>Les règles de mesure</h4><p>On le place en terrain dégagé : un arbre ou un mur arrête ou renvoie la pluie. On le lit à heure fixe (souvent le matin, pour les 24 heures écoulées), puis on le vide ; sinon, on lirait la somme de plusieurs jours.</p><h4>Le cumul</h4><p>Le cumul est la <b>somme</b> des hauteurs relevées sur une période : semaine, mois, année. Il permet de comparer des périodes ou des lieux.</p><table class='tab-lecon'><tr><th>Mot</th><th>Définition</th></tr><tr><td><b>Pluviomètre</b></td><td>Instrument qui mesure la hauteur de pluie tombée.</td></tr><tr><td><b>Précipitations</b></td><td>Eau qui tombe du ciel : pluie, neige, grêle.</td></tr><tr><td><b>Millimètre (mm)</b></td><td>Unité de hauteur ; 1 mm de pluie = 1 litre par mètre carré.</td></tr><tr><td><b>Cumul</b></td><td>Somme des hauteurs de pluie de plusieurs jours.</td></tr><tr><td><b>Mètre carré (m²)</b></td><td>Surface d'un carré d'un mètre de côté.</td></tr></table>","expert":"","dans_le_roman":"Voir la salle 3."},{"id":"releves","rayon":"lecons","fiche":4,"icone":"📖","titre":"Organiser et exploiter des relevés","escale":4,"competence":"Lire et compléter un tableau à double entrée ; Trouver un minimum, un maximum, un écart ; Repérer une valeur aberrante ; Lire un diagramme en barres ou une courbe","essentiel":"<h4>Le tableau de relevés</h4><p>Chaque jour, on note les mesures dans un <b>tableau</b>. Chaque <b>ligne</b> est une grandeur (température, vent, pluie) avec son <b>unité</b> ; chaque <b>colonne</b> est un jour.</p><div class='encadre'><b>Toujours noter :</b> le jour, l'heure, la valeur et l'unité (°C, km/h, mm).</div><h4>Comparer</h4><p>Le <b>minimum</b> est la plus petite valeur, le <b>maximum</b> la plus grande. L'<b>écart</b> est la différence entre les deux : 21 − 7 = 14 °C.</p><h4>Une valeur impossible</h4><p>Si une valeur est très différente des autres (41 °C au milieu de jours à 15 ou 20 °C), c'est souvent une <b>erreur de mesure</b> : thermomètre au soleil, mauvaise lecture. On ne la garde pas.</p>","approfondi":"<h4>Organiser les données</h4><p>Un <b>tableau à double entrée</b> croise les grandeurs mesurées (lignes) et les dates (colonnes). Une valeur sans unité ne veut rien dire : 12 peut être 12 °C, 12 km/h ou 12 mm.</p><h4>Exploiter les données</h4><p>On cherche le <b>minimum</b> et le <b>maximum</b>, on calcule l'<b>écart</b> (maximum − minimum) et le <b>cumul</b> (somme, pour la pluie).</p><h4>Représenter</h4><p>Un <b>diagramme en barres</b> convient aux quantités (pluie de chaque jour). Une <b>courbe</b> montre l'évolution d'une grandeur qui varie en continu, comme la température.</p><div class='encadre'><b>Valeur aberrante</b><br>C'est une valeur impossible ou très éloignée des autres : un minimum plus élevé que le maximum du même jour, un chiffre recopié de travers. On la repère, on cherche la cause et on ne l'utilise pas dans les calculs.</div><table class='tab-lecon'><tr><th>Mot</th><th>Définition</th></tr><tr><td><b>Relevé</b></td><td>Mesure notée avec sa date, son heure et son unité.</td></tr><tr><td><b>Tableau à double entrée</b></td><td>Tableau où chaque case croise une ligne et une colonne.</td></tr><tr><td><b>Écart</b></td><td>Différence entre la plus grande et la plus petite valeur.</td></tr><tr><td><b>Valeur aberrante</b></td><td>Valeur impossible ou très éloignée des autres, due à une erreur.</td></tr><tr><td><b>Diagramme en barres</b></td><td>Graphique où la hauteur de chaque barre représente une valeur.</td></tr></table>","expert":"","dans_le_roman":"Voir la salle 4."},{"id":"bulletin","rayon":"lecons","fiche":5,"icone":"📖","titre":"De la mesure à la prévision : météo et climat","escale":5,"competence":"Relier des mesures à une prévision et à des conseils ; Distinguer la météo et le climat","essentiel":"<h4>À quoi servent les mesures ?</h4><p>En comparant les mesures d'aujourd'hui à celles des jours précédents, les prévisionnistes annoncent le temps qu'il fera. Un <b>bulletin météo</b> donne la température, le vent, la pluie, et des <b>conseils</b> : vêtement de pluie, casquette, prudence.</p><div class='encadre'><b>Météo</b> : le temps qu'il fait <b>aujourd'hui</b> et dans les jours qui viennent. Il change très vite.<br><b>Climat</b> : le temps <b>habituel</b> d'une région, observé pendant de <b>très nombreuses années</b>.</div><p>« Demain, il pleuvra » parle de météo. « Au Sahara, il pleut très peu » parle de climat.</p>","approfondi":"<h4>Du relevé au bulletin</h4><p>Une prévision s'appuie sur des milliers de mesures fiables, prises partout de la même façon. À l'école, nos trois capteurs donnent déjà l'essentiel : température, vent, pluie. Le bulletin traduit ces nombres en décisions.</p><div class='encadre'><b>Météo</b> : l'état de l'atmosphère à un endroit et à un moment donnés ; il change d'heure en heure.<br><b>Climat</b> : une moyenne statistique de ces conditions sur une longue période. Les climatologues utilisent des <b>périodes de référence de trente ans</b> ; les moyennes obtenues s'appellent les « normales ».</div><p>Une journée froide ne dit rien, à elle seule, du climat : il faut de longues séries de mesures. C'est pourquoi les relevés de la station doivent être réguliers et bien conservés.</p><table class='tab-lecon'><tr><th>Mot</th><th>Définition</th></tr><tr><td><b>Météo</b></td><td>Le temps qu'il fait à un endroit, à un moment donné.</td></tr><tr><td><b>Climat</b></td><td>Le temps habituel d'une région, calculé sur une longue période.</td></tr><tr><td><b>Prévision</b></td><td>Annonce du temps qu'il fera, fondée sur des mesures.</td></tr><tr><td><b>Bulletin</b></td><td>Court texte qui présente la prévision et des conseils.</td></tr><tr><td><b>Normale</b></td><td>Valeur moyenne calculée sur trente ans.</td></tr></table>","expert":"","dans_le_roman":"Voir la salle 5."}]},"decors-fx":{"decors":{"abri":{"titre":"🌡️ L'abri météo, dans la cour de l'école","reference":null,"ambiance":["vent"],"kenBurns":{"echelle":1.05,"duree":32},"effets":[{"type":"poussiere","x":0,"y":0,"w":100,"h":100,"nombre":24},{"type":"vignette","force":0.5},{"type":"grain","force":0.04}],"zones":[{"id":"objet-1","libelle":"Le thermomètre de l'abri","x":6,"y":14,"w":26,"h":34,"description":"Un thermomètre à lire, y compris sous zéro."},{"id":"objet-2","libelle":"L'abri blanc à persiennes","x":37,"y":10,"w":26,"h":34,"description":"L'abri météo : où placer le thermomètre ?"},{"id":"objet-3","libelle":"Les relevés de la semaine","x":68,"y":14,"w":26,"h":34,"description":"Des températures à ranger du plus froid au plus chaud."},{"id":"objet-4","libelle":"Les fiches de mesure","x":37,"y":48,"w":26,"h":26,"description":"Des mesures fiables et d'autres faussées."}],"etats":{"normal":{"filtre":"none"}}},"mat":{"titre":"🧭 Le mât de l'anémomètre et de la girouette","reference":null,"ambiance":["vent"],"kenBurns":{"echelle":1.05,"duree":32},"effets":[{"type":"poussiere","x":0,"y":0,"w":100,"h":100,"nombre":24},{"type":"vignette","force":0.5},{"type":"grain","force":0.04}],"zones":[{"id":"objet-1","libelle":"La rose des vents","x":6,"y":14,"w":26,"h":34,"description":"Une rose des vents à compléter."},{"id":"objet-2","libelle":"La girouette et l'anémomètre","x":37,"y":10,"w":26,"h":34,"description":"Deux instruments : direction et vitesse du vent."},{"id":"objet-3","libelle":"L'échelle de Beaufort","x":68,"y":14,"w":26,"h":34,"description":"Une échelle qui décrit la force du vent."},{"id":"objet-4","libelle":"Le carnet du capitaine","x":37,"y":48,"w":26,"h":26,"description":"Le carnet de bord de Keita, aux mots manquants."}],"etats":{"normal":{"filtre":"none"}}},"pluvio":{"titre":"🌧️ Le pluviomètre, au fond du jardin","reference":null,"ambiance":["vent"],"kenBurns":{"echelle":1.05,"duree":32},"effets":[{"type":"poussiere","x":0,"y":0,"w":100,"h":100,"nombre":24},{"type":"vignette","force":0.5},{"type":"grain","force":0.04}],"zones":[{"id":"objet-1","libelle":"Le pluviomètre","x":6,"y":14,"w":26,"h":34,"description":"Un pluviomètre à lire."},{"id":"objet-2","libelle":"Le pluviomètre à graduations","x":37,"y":10,"w":26,"h":34,"description":"Un millimètre de pluie, qu'est-ce que c'est ?"},{"id":"objet-3","libelle":"Le tableau des pluies","x":68,"y":14,"w":26,"h":34,"description":"Des journées à ranger du plus sec au plus arrosé."},{"id":"objet-4","libelle":"Le cadenas du cumul","x":37,"y":48,"w":26,"h":26,"description":"Un cadenas dont le code est un cumul de pluie."}],"etats":{"normal":{"filtre":"none"}}},"bureau":{"titre":"📋 Le bureau des relevés","reference":null,"ambiance":["vent"],"kenBurns":{"echelle":1.05,"duree":32},"effets":[{"type":"poussiere","x":0,"y":0,"w":100,"h":100,"nombre":24},{"type":"vignette","force":0.5},{"type":"grain","force":0.04}],"zones":[{"id":"objet-1","libelle":"Le tableau à double entrée","x":6,"y":14,"w":26,"h":34,"description":"Un tableau où des cases sont effacées."},{"id":"objet-2","libelle":"La valeur impossible","x":37,"y":10,"w":26,"h":34,"description":"Un relevé qui n'est pas possible."},{"id":"objet-3","libelle":"La fiche d'analyse","x":68,"y":14,"w":26,"h":34,"description":"Ce que dit le tableau des relevés."},{"id":"objet-4","libelle":"Le graphique de la pluie","x":37,"y":48,"w":26,"h":26,"description":"Un graphique à barres de la pluie."}],"etats":{"normal":{"filtre":"none"}}},"studio":{"titre":"📡 La salle de prévision","reference":null,"ambiance":["vent"],"kenBurns":{"echelle":1.05,"duree":32},"effets":[{"type":"poussiere","x":0,"y":0,"w":100,"h":100,"nombre":24},{"type":"vignette","force":0.5},{"type":"grain","force":0.04}],"zones":[{"id":"objet-1","libelle":"Le mur météo et climat","x":6,"y":14,"w":26,"h":34,"description":"Météo ou climat ? Deux mots à ne pas confondre."},{"id":"objet-2","libelle":"La carte de prévision","x":37,"y":10,"w":26,"h":34,"description":"Prévoir la sortie à partir des mesures."},{"id":"objet-3","libelle":"Le bulletin","x":68,"y":14,"w":26,"h":34,"description":"Un mot caché dans le bulletin du jour."},{"id":"objet-4","libelle":"Le cadenas de la prévision","x":37,"y":48,"w":26,"h":26,"description":"Le dernier cadenas : la valeur de vérité."}],"etats":{"normal":{"filtre":"none"}}}}},"dialogues":{"_commentaire":"Brouillon généré par le migrateur : reformuler dans le ton de chaque personnage.","accueil":{"personnage":"vasseur","texte":"Bonjour. Je suis Madame Vasseur, prévisionniste. L'orage de cette nuit a déréglé votre station météo : plus aucune mesure n'est fiable. Cinq modules sont hors service. Vous allez les remettre en route, dans l'ordre."},"coffre":{"personnage":"vasseur","texte":"Le coffre ne s'ouvre qu'avec les mots de chaque salle, dans l'ordre. Vous les avez notés, j'espère."},"cinematiques":{"transition-e1":{"titre":"Salle 1 — L'abri météo","plans":[{"decor":"abri","etat":"normal","duree":8,"personnage":"vasseur","texte":"Regardez ce thermomètre, posé en plein soleil sur le muret : il ne mesure plus l'air, il mesure le soleil ! Un thermomètre se lit à l'ombre, dans son abri, et toujours à la même hauteur. Premier module : apprenez à lire la température, puis remettez l'instrument à sa place.","mouvement":"zoom"}]},"fin-e1":{"titre":"Fin de la salle 1","plans":[{"decor":"abri","etat":"normal","duree":7,"personnage":"vasseur","texte":"Premier module en service : MESURER . Mercredi, le jour de l'orage, l'air est monté à 21 °C au plus chaud. Retenez ce nombre. Maintenant, montez voir le mât du vent : le capitaine Keïta attend une direction et une vitesse.","mouvement":"glisse"}]},"transition-e2":{"titre":"Salle 2 — Le mât du vent","plans":[{"decor":"mat","etat":"normal","duree":8,"personnage":"keita","texte":"Bonjour, matelots. Sur mon bateau, deux questions décident de tout : d'où vient le vent, et à quelle vitesse il souffle. La girouette répond à la première, l'anémomètre à la seconde. Mais sans les points cardinaux, une girouette ne sert à rien. Remettez la rose des vents dans le bon sens.","mouvement":"zoom"}]},"fin-e2":{"titre":"Fin de la salle 2","plans":[{"decor":"mat","etat":"normal","duree":7,"personnage":"keita","texte":"Deuxième module en service : ORIENTER . Mercredi, l'anémomètre marquait 24 km/h de vent moyen, venant de l'ouest : une jolie brise, force 4. Parfait pour naviguer. Descendez au jardin : Tiago s'occupe du pluviomètre.","mouvement":"glisse"}]},"transition-e3":{"titre":"Salle 3 — Le pluviomètre","plans":[{"decor":"pluvio","etat":"normal","duree":8,"personnage":"tiago","texte":"Salut ! Le pluviomètre recueille la pluie qui tombe sur son ouverture. On ne compte pas des litres : on lit une hauteur d'eau, en millimètres. Chaque matin, on lit, on note, on vide. Et en additionnant les jours, on obtient le cumul. À toi de lire le tube.","mouvement":"zoom"}]},"fin-e3":{"titre":"Fin de la salle 3","plans":[{"decor":"pluvio","etat":"normal","duree":7,"personnage":"tiago","texte":"Troisième module en service : CUMULER . Mercredi, le tube indiquait 7 mm : sept litres d'eau sur chaque mètre carré de la cour. Lina t'attend au bureau des relevés : son tableau est dans un triste état.","mouvement":"glisse"}]},"transition-e4":{"titre":"Salle 4 — Le tableau des relevés","plans":[{"decor":"bureau","etat":"normal","duree":8,"personnage":"lina","texte":"Coucou ! C'est moi qui tiens le cahier de la station. Mesurer chaque jour, c'est bien, mais si les nombres sont mélangés, on ne peut rien en tirer. Un tableau bien rangé, ça permet de comparer : quel jour était le plus froid ? le plus arrosé ? Tu m'aides à tout remettre en ordre ?","mouvement":"zoom"}]},"fin-e4":{"titre":"Fin de la salle 4","plans":[{"decor":"bureau","etat":"normal","duree":7,"personnage":"lina","texte":"Quatrième module en service : ORGANISER . Mon tableau est propre, et on voit tout d'un coup d'œil. Il reste le plus important : transformer ces mesures en bulletin pour la sortie. Madame Vasseur t'attend dans la salle de prévision.","mouvement":"glisse"}]},"transition-e5":{"titre":"Salle 5 — Le bulletin du jour","plans":[{"decor":"studio","etat":"normal","duree":8,"personnage":"vasseur","texte":"Dernier module. Mesurer, c'est bien ; prévoir, c'est mieux. La météo, c'est le temps qu'il fait aujourd'hui et dans les jours qui viennent. Le climat, c'est autre chose : une moyenne sur trente ans. Montrez-moi que vous ne les confondez pas, puis entrez la valeur de vérité de mercredi : la température maximale, la vitesse du vent et la hauteur de pluie.","mouvement":"zoom"}]},"fin-e5":{"titre":"Fin de la salle 5","plans":[{"decor":"studio","etat":"normal","duree":7,"personnage":"vasseur","texte":"Le bulletin est à l'antenne ! Mesurer, orienter, cumuler, organiser, pour prévoir : c'est tout le travail d'une station. Demain matin, on recommence les relevés dans la cour. Tu viens avec moi ?","mouvement":"glisse"}]},"fin":{"titre":"Fin de « La Station météo disparue »","plans":[{"decor":"studio","etat":"normal","duree":7,"personnage":"vasseur","texte":"Le coffre est ouvert : toutes les pages sont rassemblées. Bravo, équipe !","mouvement":"zoom"}]}},"fin_escale":{"1":{"personnage":"vasseur","texte":"Notez le mot de cette salle : il servira à ouvrir le coffre final."},"2":{"personnage":"keita","texte":"Notez le mot de cette salle : il servira à ouvrir le coffre final."},"3":{"personnage":"tiago","texte":"Notez le mot de cette salle : il servira à ouvrir le coffre final."},"4":{"personnage":"lina","texte":"Notez le mot de cette salle : il servira à ouvrir le coffre final."},"5":{"personnage":"vasseur","texte":"Notez le mot de cette salle : il servira à ouvrir le coffre final."}}},"personnages":{"personnages":{"vasseur":{"nom":"Madame Vasseur","court":"Madame","voix":{"edge":"fr-FR-VivienneMultilingualNeural","nom":"Vivienne","rate":0.95,"pitch":1.0},"ton":"Prévisionniste rassurante, rigoureuse","fiche":"Prévisionniste, marraine de la station de l'école","portrait":{"genre":"femme","coiffure":"courte","cheveux":"#9c9c98","peau":"#e6c2a6","habit":"#3a3a52","lunettes":true}},"tiago":{"nom":"Tiago","court":"Tiago","voix":{"edge":"fr-FR-HenriNeural","nom":"Henri","rate":1.0,"pitch":1.0},"ton":"Technicien pragmatique, toujours une clé à molette","fiche":"Technicien de station météo","portrait":{"genre":"homme","coiffure":"courte","cheveux":"#2a1c14","peau":"#c08a64","habit":"#2a5a8a","barbe":false,"lunettes":false}},"lina":{"nom":"Lina","court":"Lina","voix":{"edge":"fr-FR-EloiseNeural","nom":"Eloise","rate":1.05,"pitch":1.05},"ton":"Élève sérieuse, fière de sa station","fiche":"Élève de CM2, responsable de la station de l'école","portrait":{"genre":"fille","coiffure":"longue","cheveux":"#1a1a1a","peau":"#b8805e","habit":"#c0502a","lunettes":false}},"keita":{"nom":"Capitaine Keïta","court":"Capitaine","voix":{"edge":"fr-FR-RemyMultilingualNeural","nom":"Remy","rate":0.92,"pitch":0.9},"ton":"Capitaine du vent, parle comme un marin","fiche":"Marin, dépend du vent pour sortir en mer","portrait":{"genre":"homme","coiffure":"chauve","cheveux":"#1a1a1a","peau":"#6e4630","habit":"#1b2a4a","barbe":true,"lunettes":false}}}}};
